355:     ////////////////////////////////////////////////////////////////
356:     // Fig accessors
357: 
358:     public void setLineColor(Color col) {
359:         // The _text element has no border, so the line color doesn't matter.
360:         _body.setLineColor(col);
361:         _urCorner.setLineColor(col);
362:     }
363: 
364:     public Color getLineColor() {
365:         return _body.getLineColor();
366:     }
367: 
368:     public void setFillColor(Color col) {
369:         _body.setFillColor(col);
370:         _urCorner.setFillColor(col);
371:     }
372: 
373:     public Color getFillColor() {
374:         return _body.getFillColor();
375:     }
376: 
377:     public void setFilled(boolean f) {
378:         _text.setFilled(false); // The text is always opaque.
379:         _body.setFilled(f);
380:         _urCorner.setFilled(f);
381:     }
382: 
383:     public boolean getFilled() {
384:         return _body.getFilled();
385:     }
386: 
387:     public void setLineWidth(int w) {
388:         _text.setLineWidth(0); // Make a seamless integration of the text
389:         // in the note figure.
390:         _body.setLineWidth(w);
391:         _urCorner.setLineWidth(w);
392:     }
393: 
394:     public int getLineWidth() {
395:         return _body.getLineWidth();
396:     }
397: 
398:     ////////////////////////////////////////////////////////////////
399:     // user interaction methods
400: 
401:     protected void textEdited(FigText ft) throws PropertyVetoException {
402:         if (ft == _text)
403:             storeNote(ft.getText());
404:     }
405: 
406:     public void setEnclosingFig(Fig encloser) {
407:         super.setEnclosingFig(encloser);
408:     }
409: 
410:     ////////////////////////////////////////////////////////////////
411:     // accessor methods
412: 
413:     /**
414:      * Store a note in the associated model element.
415:      *
416:      * @param note The note to store.
417:      */
418:     public final void storeNote(String note) {
419:         if (getOwner() != null)
420:              ModelFacade.setName(getOwner(), note);
421:     }
