190:     /**
191:      * Returns the correct helper on basis of the package of base
192:      * @param base the modelelement
193:      * @return Object the helper
194:      */
195:     public Object getHelper(Object base) {
196:     	if (base instanceof MBase) {
197: 	    String name = base.getClass().getName();
198: 	    name = name.substring(0, name.lastIndexOf('.'));
199: 	    name = name.substring(name.lastIndexOf('.') + 1, name.length());
200: 	    Method[] methods = this.getClass().getMethods();
201: 	    for (int i = 0; i < methods.length; i++) {
202: 		String methodname = methods[i].getName();
203: 		if (methodname.toLowerCase().indexOf(name) >= 0) {
204: 		    try {
205: 			return methods[i].invoke(this, new Object[] {});
206: 		    } catch (IllegalAccessException e) {
207:                         LOG.warn(e);
208: 		    } catch (InvocationTargetException e) {
209:                         LOG.warn(e);
210: 		    }
211: 		}
212: 	    }
213:     	}
214:     	return null;
215:     }
