116:   public void hitHandle(Rectangle r, Handle h) {
117:     super.hitHandle(r, h);
118:     if (h.index != -1) return;
119:     if (!_paintButtons) return;
120:     Editor ce = Globals.curEditor();
121:     SelectionManager sm = ce.getSelectionManager();
122:     if (sm.size() != 1) return;
123:     ModeManager mm = ce.getModeManager();
124:     if (mm.includes(ModeModify.class) && _pressedButton == -1) return;
125:     int cx = _content.getX();
126:     int cy = _content.getY();
127:     int cw = _content.getWidth();
128:     int ch = _content.getHeight();
129:     int iw = trans.getIconWidth();
130:     int ih = trans.getIconHeight();
131:     int iwd = transDown.getIconWidth();
132:     int ihd = transDown.getIconHeight();
133:     if (_showOutgoingRight && hitLeft(cx + cw, cy + ch/2, iw, ih, r)) {
134:       h.index = 12;
135:       h.instructions = "Add an outgoing transition";
136:     }
137:     else if (_showIncomingLeft && hitRight(cx, cy + ch/2, iw, ih, r)) {
138:       h.index = 13;
139:       h.instructions = "Add an incoming transition";
140:     }
141:     else if (_showOutgoingBelow && hitAbove(cx+cw/2, cy, iwd, ihd, r)) {
142:         h.index=14;
143:         h.instructions = "Add an incoming transaction";
144:     }
145:     else if (_showIncomingAbove && hitBelow(cx+cw/2,cy+ch, iwd, ihd, r)) {
146:         h.index=15;
147:         h.instructions = "Add an outgoing transaction";
148:     }
149:     else {
150:       h.index = -1;
151:       h.instructions = "Move object(s)";
152:     }
153:   }
