142:         h.index=14;
143:         h.instructions = "Add an incoming transaction";
144:     }
145:     else if (_showIncomingAbove && hitBelow(cx+cw/2,cy+ch, iwd, ihd, r)) {
146:         h.index=15;
147:         h.instructions = "Add an outgoing transaction";
148:     }
