72:   ////////////////////////////////////////////////////////////////
73:   // constructors
74: 
75:   /** Construct a new SelectionComponentInstanceInstance for the given Fig */
76:   public SelectionComponentInstance(Fig f) { super(f); }
77: 
78:   public void hitHandle(Rectangle r, Handle h) {
79:     super.hitHandle(r, h);
80:     if (h.index != -1) return;
81:     if (!_paintButtons) return;
82:     Editor ce = Globals.curEditor();
83:     SelectionManager sm = ce.getSelectionManager();
84:     if (sm.size() != 1) return;
85:     ModeManager mm = ce.getModeManager();
86:     if (mm.includes(ModeModify.class) && _pressedButton == -1) return;
87:     int cx = _content.getX();
88:     int cy = _content.getY();
89:     int cw = _content.getWidth();
90:     int ch = _content.getHeight();
91:     int aw = dep.getIconWidth();
92:     int ah = dep.getIconHeight();
93:     if (hitAbove(cx + cw/2, cy, aw, ah, r)) {
94:       h.index = 10;
95:       h.instructions = "Add a component-instance";
96:     }
97:     else if (hitBelow(cx + cw/2, cy + ch, aw, ah, r)) {
98:       h.index = 11;
99:       h.instructions = "Add a component-instance";
100:     }
101:     else if (hitLeft(cx + cw, cy + ch/2, aw, ah, r)) {
102:       h.index = 12;
103:       h.instructions = "Add a component-instance";
104:     }
105:     else if (hitRight(cx, cy + ch/2, aw, ah, r)) {
106:       h.index = 13;
107:       h.instructions = "Add a component-instance";
108:     }
109:     else {
110:       h.index = -1;
111:       h.instructions = "Move object(s)";
112:     }
113:   }
