116:   /** Paint the handles at the four corners and midway along each edge
117:    * of the bounding box.  */
118:   public void paintButtons(Graphics g) {
119:     int cx = _content.getX();
120:     int cy = _content.getY();
121:     int cw = _content.getWidth();
122:     int ch = _content.getHeight();
123:     paintButtonAbove(dep, g, cx + cw/2, cy, 10);
124:     paintButtonBelow(dep, g, cx + cw/2, cy + ch, 11);
125:     paintButtonLeft(depRight, g, cx + cw, cy + ch/2, 12);
126:     paintButtonRight(depRight, g, cx, cy + ch/2, 13);
127:   }
