130:   public void dragHandle(int mX, int mY, int anX, int anY, Handle hand) {
131:     if (hand.index < 10) {
132:       _paintButtons = false;
133:       super.dragHandle(mX, mY, anX, anY, hand);
134:       return;
135:     }
136:     int cx = _content.getX(), cy = _content.getY();
137:     int cw = _content.getWidth(), ch = _content.getHeight();
138:     int newX = cx, newY = cy, newW = cw, newH = ch;
139:     Dimension minSize = _content.getMinimumSize();
140:     int minWidth = minSize.width, minHeight = minSize.height;
141:     Class edgeClass = null;
142:     Class nodeClass = MComponentInstanceImpl.class;
143:     int bx = mX, by = mY;
144:     boolean reverse = false;
145:     switch (hand.index) {
146:     case 10: //add dep
147:       edgeClass = MDependency.class;
148:       // reverse = true;
149:       by = cy;
150:       bx = cx + cw/2;
151:       break;
152:     case 11: //add dep
153:       edgeClass = MDependency.class;
154:       reverse = true;
155:       by = cy + ch;
156:       bx = cx + cw/2;
157:       break;
158:     case 12: //add dep
159:       edgeClass = MDependency.class;
160:       // reverse = true;
161:       by = cy + ch/2;
162:       bx = cx + cw;
163:       break;
164:     case 13: // add dep
165:       edgeClass = MDependency.class;
166:       reverse = true;
167:       by = cy + ch/2;
168:       bx = cx;
169:       break;
170:     default:
171:       cat.warn("invalid handle number");
172:       break;
173:     }
174:     if (edgeClass != null && nodeClass != null) {
175:       Editor ce = Globals.curEditor();
176:       ModeCreateEdgeAndNode m = new
177: 	ModeCreateEdgeAndNode(ce, edgeClass, nodeClass, false);
178:       m.setup((FigNode)_content, _content.getOwner(), bx, by, reverse);
179:       ce.mode(m);
180:     }
181: 
182:   }
