185:   public void buttonClicked(int buttonCode) {
186:     super.buttonClicked(buttonCode);
187:     MComponentInstance newNode = UmlFactory.getFactory().getCommonBehavior().createComponentInstance();
188:     FigComponentInstance fc = (FigComponentInstance) _content;
189:     MComponentInstance cls = (MComponentInstance) fc.getOwner();
190: 
191:     Editor ce = Globals.curEditor();
192:     GraphModel gm = ce.getGraphModel();
193:     if (!(gm instanceof MutableGraphModel)) return;
194:     MutableGraphModel mgm = (MutableGraphModel) gm;
195: 
196:     if (!mgm.canAddNode(newNode)) return;
197:     GraphNodeRenderer renderer = ce.getGraphNodeRenderer();
198:     LayerPerspective lay = (LayerPerspective)
199:       ce.getLayerManager().getActiveLayer();
200:     Fig newFC = renderer.getFigNodeFor(gm, lay, newNode);
201: 
202:     Rectangle outputRect = new Rectangle(Math.max(0, fc.getX() - 200),
203: 					 Math.max(0, fc.getY() - 200),
204: 					 fc.getWidth() + 400,
205: 					 fc.getHeight() + 400);
206:    // handle the case that it is not a self association
207:         if (buttonCode >=10 && buttonCode <= 13) {
208:             int x = 0;
209:             int y = 0; 
210:             if (buttonCode == 10) {
211:                 // superclass
212:                 x = fc.getX();
213:                 y = Math.max(0, fc.getY() - 200);
214:             }
215:             else if (buttonCode == 11) {
216:                 x = fc.getX();
217:                 y = fc.getY() + fc.getHeight() + 100;
218:             }
219:             else if (buttonCode == 12) {
220:                 x = fc.getX() + fc.getWidth() + 100;
221:                 y = fc.getY();
222:             }
223:             else if (buttonCode == 13) {
224:                 x = Math.max(0, fc.getX() - 200);
225:                 y = fc.getY();
226:                 
227:             }        
228:             // place the fig if it is not a selfassociation       
229:             if (!placeFig(newFC, lay, x, y, outputRect)) return;
230:         }
231:     ce.add(newFC);
232:     mgm.addNode(newNode);
233: 
234:     FigPoly edgeShape = new FigPoly();
235:     Point fcCenter = fc.center();
236:     edgeShape.addPoint(fcCenter.x, fcCenter.y);
237:     Point newFCCenter = newFC.center();
238:     edgeShape.addPoint(newFCCenter.x, newFCCenter.y);
239:     Object newEdge = null;
240: 
241:     if (buttonCode == 10) newEdge = createEdgeAbove(mgm, cls, newNode);
242:     else if (buttonCode == 11) newEdge = createEdgeBelow(mgm, cls, newNode);
243:     else if (buttonCode == 12) newEdge = createEdgeRight(mgm, cls, newNode);
244:     else if (buttonCode == 13) newEdge = addCompClassLeft(mgm, cls, newNode);
245: 
246:     FigEdge fe = (FigEdge) lay.presentationFor(newEdge);
247:     edgeShape.setLineColor(Color.black);
248:     edgeShape.setFilled(false);
249:     edgeShape._isComplete = true;
250:     fe.setFig(edgeShape);
251:     ce.getSelectionManager().select(fc);
252:   }
