106:     /**
107:      * Returns all namespaces found in this namespace and in its children
108:      *
109:      * This method is CPU intensive and therefore needs to be as efficient as
110:      * possible.
111:      *
112:      * @param ns namespace to process
113:      * @return Collection of all namespaces found
114:      */
115:     public Collection getAllNamespaces(Object ns) {
116:         if (ns == null || !(ns instanceof MNamespace)) {
117:             return new ArrayList();
118:         }
119: 
120:         Collection namespaces = ((MNamespace) ns).getOwnedElements();
121:         // the list of namespaces to return
122:         List list = Collections.EMPTY_LIST;
123: 
124:         // if there are no owned elements then return empty list
125:         if (namespaces == Collections.EMPTY_LIST
126: 	    || namespaces.size() == 0) {
127:             return Collections.EMPTY_LIST;
128:         }
129: 
130:         // work with an array instead of iterator.
131:         Object[] nsArray = namespaces.toArray();
132: 
133:         for (int i = 0; i < nsArray.length; i++) {
134: 
135:             Object o = nsArray[i];
136:             if (o instanceof MNamespace) {
137: 
138:                 // only build a namepace if needed, with
139:                 if (list == Collections.EMPTY_LIST) {
140:                     list = new ArrayList(nsArray.length);
141:                 }
142: 
143:                 list.add(o);
144: 
145:                 Collection namespaces1 = getAllNamespaces(o);
146:                 // only add all if there are some to add.
147:                 if (namespaces1 != Collections.EMPTY_LIST
148:                         && namespaces1.size() > 0) {
149:                     list.addAll(namespaces1);
150:                 }
151:             }
152:         }
153:         return list;
154:     }
