257:      *             for NSUML.
258:      * @return a Collection.
259:      */
260:     public Collection getAllModelElementsOfKind(Object nsa, String kind) {
261: 
262:         if (nsa == null || kind == null) {
263:             return Collections.EMPTY_LIST;
264:         }
265:         if (!ModelFacade.isANamespace(nsa)) {
266:             throw new IllegalArgumentException(
267:                 "given argument " + nsa + " is not a namespace");
