280:     /**
281:      * Returns all surrounding namespaces of some namespace ns. See
282:      * section 2.5.3.24 of the UML 1.3 spec for a definition.
283:      * @param ns to process
284:      * @return Collection of surrounding namespaces.
285:      */
286:     public Collection getAllSurroundingNamespaces(Object ns) {
287:         if (!(ns instanceof MNamespace)) {
288:             throw new IllegalArgumentException();
289:         }
290: 
291:         Set set = new HashSet();
292:         set.add(ns);
293:         MNamespace namespace = ((MNamespace) ns);
294:         if (namespace.getNamespace() != null) {
295:             set.addAll(getAllSurroundingNamespaces(namespace.getNamespace()));
296:         }
