162:     public Collection getAllModelElementsOfKindWithModel(Object type) {
163:         Class kind = (Class) type;
164:         if (kind == null) {
165:             return Collections.EMPTY_LIST;
166:         }
167:         Project p = ProjectManager.getManager().getCurrentProject();
168:         MNamespace model = (MModel) p.getRoot();
169:         Collection ret = getAllModelElementsOfKind(model, kind);
170:         if (kind.isAssignableFrom(model.getClass())) {
