54: /** User interface panel shown at the bottom of the screen that allows
55:  *  the user to edit the properties of the selected UML model
56:  *  element. */
57: 
58: public class PropPanelComponentInstance extends PropPanel 
59: implements ItemListener, DocumentListener {
60: 
61:   ////////////////////////////////////////////////////////////////
62:   // constants
63:   // needs-more-work 
64: 
65:   ////////////////////////////////////////////////////////////////
66:   // instance vars
67:   JLabel _baseLabel = new JLabel("Base : "); 
68:   JTextField _baseField = new JTextField(); 
69:   public JLabel _deploymentLocationLabel = new JLabel("Node-Instance: ");
70:   public static JTextField _deploymentLocationField = new JTextField();
71: 
72:   // declare and initialize all widgets
73:   ////////////////////////////////////////////////////////////////
74:   // contructors
75:   public PropPanelComponentInstance() {
76:     super("ComponentInstance Properties");
77:     _deploymentLocationField.setEditable(false);
78:     GridBagLayout gb = (GridBagLayout) getLayout();
79:     GridBagConstraints c = new GridBagConstraints();
80:     c.fill = GridBagConstraints.BOTH;
81:     c.weightx = 0.0;
82:     c.ipadx = 0; c.ipady = 0;
83: 
84: 
85:     c.gridx = 0;
86:     c.gridwidth = 1;
87:     c.gridy = 1; 
88:     c.weightx = 0.0; 
89:     gb.setConstraints(_baseLabel, c); 
90:     add(_baseLabel); 
91:     c.gridy = 2;
92:     gb.setConstraints(_deploymentLocationLabel, c);
93:     add(_deploymentLocationLabel);
94:         
95:     c.weightx = 1.0; 
96:     c.gridx = 1; 
97:     c.gridy = 1; 
98:     _baseField.setMinimumSize(new Dimension(120, 20)); 
99:     gb.setConstraints(_baseField, c); 
100:     add(_baseField); 
101:     _baseField.getDocument().addDocumentListener(this); 
102:     _baseField.setFont(_stereoField.getFont()); 
103:     c.gridy = 2;
104:     _deploymentLocationField.setMinimumSize(new Dimension(120, 20));
105:     gb.setConstraints(_deploymentLocationField, c);
106:     add(_deploymentLocationField);
107:     _deploymentLocationField.getDocument().addDocumentListener(this);
108:     _deploymentLocationField.setFont(_stereoField.getFont());
109: 
110:   }
111: 
112:   ////////////////////////////////////////////////////////////////
113:   // accessors
114: 
115:   /** Set the values to be shown in all widgets based on model */
116:   protected void setTargetInternal(Object t) {
117:     super.setTargetInternal(t);
118:     MComponentInstance coi = (MComponentInstance) t;
119:     if (coi.getNodeInstance() != null) {
120:       MNodeInstance node = (MNodeInstance) coi.getNodeInstance();
121:       _deploymentLocationField.setText(node.getName());
122:     }
123:     else {
124:       _deploymentLocationField.setText(null);
125:     }
126: 
127:     if (coi.getClassifiers() != null) { 
128:       String base = ""; 
129:       Collection classifiers = coi.getClassifiers(); 
130:       Iterator it = classifiers.iterator(); 
131:       while (it.hasNext()) { 
132:         Object o = it.next(); 
133:         if (o != null && (o instanceof MClassifier)) { 
134:           MClassifier cls = (MClassifier) o; 
135:           if (cls != null) { 
136:             base = cls.getName(); 
137:           } 
138:         } 
139:       } 
140:       _baseField.setText(base);         
141:     }  
142:     else { 
143:       _baseField.setText(null); 
144:     } 
145: 
146:     validate();
147:   }
148:   
149:   public void setTargetBase() {  
150:     if (_target == null) return;  
151:     if (_inChange) return; 
152:   
153:     MComponentInstance coi = (MComponentInstance) _target; 
154:     MComponent classifier = new MComponentImpl();  
155:     String base = _baseField.getText(); 
156:     Collection col = coi.getClassifiers(); 
157:     if ((col != null) && (col.size()>0)) {  
158:       Iterator itcol = col.iterator();  
159:       while (itcol.hasNext()) {  
160:         MClassifier cls = (MClassifier) itcol.next();  
161:         coi.removeClassifier(cls);  
162:       }  
163:     }  
164:  
165:     Vector diagrams = ProjectBrowser.TheInstance.getProject().getDiagrams(); 
166:     GraphModel model = null; 
167:     Vector v = new Vector(); 
168:     int size = diagrams.size(); 
169:     for (int i=0; i<size; i++) { 
170:       Object o = diagrams.elementAt(i); 
171:       if (!(o instanceof Diagram)) continue; 
172:       if (o instanceof MModel) continue; 
173:       Diagram d = (Diagram) o; 
174:       model = d.getGraphModel();  
175:  
176:       if (!(model instanceof DeploymentDiagramGraphModel)) continue; 
177:         
178:       Vector nodes = model.getNodes(); 
179:       int s = nodes.size(); 
180:       for (int j=0; j<s; j++) { 
181:         MModelElement node = (MModelElement) nodes.elementAt(j); 
182:         if (node != null && (node instanceof MComponentImpl)) { 
183:           MComponent mcomp = (MComponent) node; 
184:           if (mcomp.getNamespace() != coi.getNamespace()) continue;
185:           String comp_name = mcomp.getName(); 
186:           if (comp_name != null && (comp_name.equals(base))) { 
187:             v.addElement(mcomp); 
188:             coi.setClassifiers(v); 
189:             return;  
190:           }       
191:         } 
192:       } 
193:     } 
194:  
195:     classifier.setName(base); 
196:     v.addElement(classifier); 
197:     coi.setClassifiers(v); 
198:  
199:     //System.out.println("needs-more-work: baseClass = " + base);  
200:     // needs-more-work: this could involve changes to the graph model  
201:   }  
202:  
203: 
