77:     _deploymentLocationField.setEditable(false);
78:     GridBagLayout gb = (GridBagLayout) getLayout();
79:     GridBagConstraints c = new GridBagConstraints();
80:     c.fill = GridBagConstraints.BOTH;
81:     c.weightx = 0.0;
82:     c.ipadx = 0; c.ipady = 0;
83: 
84: 
85:     c.gridx = 0;
86:     c.gridwidth = 1;
87:     c.gridy = 1; 
88:     c.weightx = 0.0; 
89:     gb.setConstraints(_baseLabel, c); 
90:     add(_baseLabel); 
91:     c.gridy = 2;
92:     gb.setConstraints(_deploymentLocationLabel, c);
93:     add(_deploymentLocationLabel);
94:         
95:     c.weightx = 1.0; 
96:     c.gridx = 1; 
97:     c.gridy = 1; 
98:     _baseField.setMinimumSize(new Dimension(120, 20)); 
99:     gb.setConstraints(_baseField, c); 
100:     add(_baseField); 
101:     _baseField.getDocument().addDocumentListener(this); 
102:     _baseField.setFont(_stereoField.getFont()); 
103:     c.gridy = 2;
104:     _deploymentLocationField.setMinimumSize(new Dimension(120, 20));
105:     gb.setConstraints(_deploymentLocationField, c);
106:     add(_deploymentLocationField);
107:     _deploymentLocationField.getDocument().addDocumentListener(this);
108:     _deploymentLocationField.setFont(_stereoField.getFont());
109: 
110:   }
