210:     //System.out.println(getClass().getName() + " insert");
211:     // check if it was one of my text fields
212:     super.insertUpdate(e);
213:     if (e.getDocument() == _baseField.getDocument()) { 
214:       setTargetBase(); 
215:     } 
216:  }
217: 
218:   public void removeUpdate(DocumentEvent e) { insertUpdate(e); }
219: 
220:   public void changedUpdate(DocumentEvent e) {
221:     System.out.println(getClass().getName() + " changed");
222:     // Apparently, this method is never called.
223:   }
