153:     public Object buildAbstraction(String name, Object supplier, 
154:             Object client) {
155:         if (!(client instanceof Classifier)
156:                 || !(supplier instanceof Classifier)) {
157:             throw new IllegalArgumentException(
158:                     "The supplier and client of an abstraction"
159:                             + "should be classifiers");
160:         }
161:         Abstraction abstraction = (Abstraction) createAbstraction();
162:         abstraction.setName(name);
163:         abstraction.getClient().add(client);
164:         abstraction.getSupplier().add(supplier);
165:         return abstraction;
166:     }
