547:     public Object buildAssociation(Object classifier1, Object classifier2) {
548:         Classifier c1 = (Classifier) classifier1;
549:         Classifier c2 = (Classifier) classifier2;
550:         return buildAssociation(c1, true, AggregationKindEnum.AK_NONE, c2,
551:                 true, AggregationKindEnum.AK_NONE);
552:     }
