574:         if (end1 == null || end2 == null || !(end1 instanceof Classifier)
575:                 || !(end2 instanceof Classifier)) {
576:             throw new IllegalArgumentException(
577:                     "either one of the arguments was null");
578:         }
579:         return buildAssociationClass(
580:                 (UmlClass) buildClass(),
581:                 (Classifier) end1,
582:                 (Classifier) end2);
583:     }
