1659:     /*
1660:      * Remove a trailing slash, including the entire line if it's the only thing
1661:      * on the line. 
1662:      */
1663:     private String removeTrailingSlash(String s) {
1664:         if (s.endsWith("\n/")) {
1665:             return s.substring(0, s.length() - 2);
1666:         } else  if (s.endsWith("/")) {
1667:             return s.substring(0, s.length() - 1);
1668:         } else {
1669:             return s;
1670:         }
1671:     }
1672:     
1673:     /*
1674:      * If there is a tagged value named 'stereotype', make it a real
1675:      * stereotype and remove the tagged value.
1676:      * We allow multiple instances of this tagged value 
1677:      * AND parse a single instance for multiple stereotypes
1678:      */
1679:     private void addStereotypes(Object modelElement) {
1680:         Object tv = Model.getFacade()
1681:                 .getTaggedValue(modelElement, "stereotype");
1682:         if (tv != null) {
1683:             String stereo = Model.getFacade().getValueOfTag(tv);
1684:             if (stereo != null && stereo.length() > 0) {
1685:                 StringTokenizer st = new StringTokenizer(stereo, ", ");
1686:                 while (st.hasMoreTokens()) {
1687:                     Model.getCoreHelper().addStereotype(modelElement,
1688:                             getStereotype(st.nextToken().trim()));
1689:                 }
1690:             }
1691:             Model.getExtensionMechanismsHelper().removeTaggedValue(
1692:                     modelElement, tv);
1693:         }
1694:     }
