176:     /**
177:      * This is a mapping from a Java compilation Unit -> a UML component.
178:      * Classes are resident in a component.
179:      * Imports are relationships between components and other classes
180:      * / packages.<p>
181:      *
182:      * See JSR 26.<p>
183:      *
184:      * Adding components is a little messy since there are 2 cases:
185:      *
186:      * <ol>
187:      * <li>source file has package statement, will be added several times
188:      *     since lookup in addComponent() only looks in the model since the
189:      *     package namespace is not yet known.
190:      *
191:      * <li>source file has not package statement: component is added
192:      *     to the model namespace. the is no package statement so the
193:      *     lookup will always work.
194:      *
195:      * </ol>
196:      * Therefore in the case of (1), we need to delete duplicate components
197:      * in the addPackage() method.<p>
198:      *
199:      * In either case we need to add a package since we don't know in advance
200:      * if there will be a package statement.<p>
201:      */
202:     public void addComponent() {
203: 
204:         // try and find the component in the current package
205:         // to cope with repeated imports
206:         // [this will never work if a package statmeent exists:
207:         // because the package statement is parsed after the component is
208:         // identified]
209:         Object component = Model.getFacade().lookupIn(currentPackage, fileName);
210: 
211:         if (component == null) {
212: 
213:             // remove the java specific ending (per JSR 26).
214:             // BUT we can't do this because then the component will be confused
215:             // with its class with the same name when invoking
216:             // Model.getFacade().lookupIn(Object,String)
217:             /*
218: 	      if(fileName.endsWith(".java"))
219: 	      fileName = fileName.substring(0, fileName.length()-5);
220:             */
221: 
222:             component = Model.getCoreFactory().createComponent();
223:             Model.getCoreHelper().setName(component, fileName);
224:         }
225: 
226:         parseState.addComponent(component);
227: 
228:         // set the namespace of the component, in the event
229:         // that the source file does not have a package stmt
230:         Model.getCoreHelper().setNamespace(parseState.getComponent(), model);
231:     }
