233:     /**
234:      * Called from the parser when a package clause is found.
235:      *
236:      * @param name The name of the package.
237:      */
238:     public void addPackage(String name) {
239: 	// Add a package figure for this package to the owners class
240: 	// diagram, if it's not in the diagram yet. I do this for all
241: 	// the class diagrams up to the top level, since I need
242: 	// diagrams for all the packages.
243: 	String ownerPackageName, currentName = name;
244:         ownerPackageName = getPackageName(currentName);
245: 	while (!"".equals(ownerPackageName)) {
246: 	    if (getDiagram() != null
247: 		&& importSession != null
248:                 && importSession.isCreateDiagramsChecked()
249: 		&& getDiagram().isDiagramInProject(ownerPackageName)) {
250: 
251:                 getDiagram().selectClassDiagram(getPackage(ownerPackageName),
252: 						ownerPackageName);
253:                 getDiagram().addPackage(getPackage(currentName));
254: 
255:             }
256: 	    currentName = ownerPackageName;
257:             ownerPackageName = getPackageName(currentName);
258: 	}
259: 	// Save src_path in the upper package
260: 	Object mPackage = getPackage(currentName);
261: 	if (importSession != null && importSession.getSrcPath() != null
262: 	    && Model.getFacade().getTaggedValue(mPackage, "src_path") == null) {
263: 	    Model.getCoreHelper().setTaggedValue(mPackage, "src_path",
264: 				       importSession.getSrcPath());
265: 	}
266: 
267: 	// Find or create a Package model element for this package.
268: 	mPackage = getPackage(name);
269:         currentPackageName = name;
270: 
271: 	// Set the current package for the following source code.
272: 	currentPackage = mPackage;
273: 	parseState.addPackageContext(mPackage);
274: 
275:         // Delay diagram creation until any classifier (class or
276:         // interface) will be found
277: 
278:         //set the namespace of the component
279:         // check to see if there is already a component defined:
280:         Object component = Model.getFacade().lookupIn(currentPackage, fileName);
281: 
282:         if (component == null) {
283: 
284:             // set the namespace of the component
285:             Model.getCoreHelper().setNamespace(
286:                     parseState.getComponent(),
287:                     currentPackage);
288:         } else {
289: 
290:             // a component already exists,
291:             // so delete the latest one(the duplicate)
292:             Model.getUmlFactory().delete(parseState.getComponent());
293:         // change the parse state to the existing one.
294:             parseState.addComponent(component);
295:         }
296:     }
