298:     /**
299:      * Called from the parser when an import clause is found.
300:      *
301:      * @param name The name of the import. Can end with a '*'.
302:      */
303:     public void addImport(String name) {
304:         // only do imports on the 2nd pass.
305:         Object level = this.getAttribute("level");
306:         if (level != null) {
307:             if (level.equals(new Integer(0))) {
308:                 return;
309:             }
310:         }
311: 
312: 	String packageName = getPackageName(name);
313: 	String classifierName = getClassifierName(name);
314: 	Object mPackage = getPackage(packageName);
315: 
316:         // import on demand
317: 	if (classifierName.equals("*")) {
318: 	    parseState.addPackageContext(mPackage);
319:             Object perm = null;
320: 
321:             // try find an existing permission
322:             Iterator dependenciesIt =
323:                 Model.getCoreHelper()
324: 		    .getDependencies(mPackage, parseState.getComponent())
325: 		        .iterator();
326:             while (dependenciesIt.hasNext()) {
327: 
328:                 Object dependency = dependenciesIt.next();
329:                 if (Model.getFacade().isAPermission(dependency)) {
330: 
331:                     perm = dependency;
332:                     break;
333:                 }
334:             }
335: 
336:             // if no existing permission was found.
337:             if (perm == null) {
338: 		perm =
339: 		    Model.getCoreFactory()
340: 		        .buildPermission(parseState.getComponent(), mPackage);
341: 		String newName =
342: 		    Model.getFacade().getName(parseState.getComponent())
343: 		    + " -> "
344: 		    + packageName;
345: 		Model.getCoreHelper().setName(perm, newName);
346:             }
347: 	}
348:         // single type import
349: 	else {
350:             Object mClassifier = null;
351: 	    try {
352: 		mClassifier =
353: 		    (new PackageContext(null, mPackage)).get(classifierName);
354: 		parseState.addClassifierContext(mClassifier);
355:                 Object perm = null;
356: 
357:                 // try find an existing permission
358:                 Iterator dependenciesIt =
359: 		    Model.getCoreHelper()
360:                         .getDependencies(mClassifier,
361: 					 parseState.getComponent())
362:                             .iterator();
363:                 while (dependenciesIt.hasNext()) {
364: 
365:                     Object dependency = dependenciesIt.next();
366:                     if (Model.getFacade().isAPermission(dependency)) {
367: 
368:                         perm = dependency;
369:                         break;
370:                     }
371:                 }
372: 
373:                 // if no existing permission was found.
374:                 if (perm == null) {
375:                     perm =
376: 			Model.getCoreFactory()
377: 			    .buildPermission(parseState.getComponent(),
378: 					     mClassifier);
379: 		    String newName =
380: 			Model.getFacade().getName(parseState.getComponent())
381: 			+ " -> "
382: 			+ Model.getFacade().getName(mClassifier);
383:                     Model.getCoreHelper().setName(perm, newName);
384:                 }
385: 	    } catch (ClassifierNotFoundException e) {
386: 		// Currently if a classifier cannot be found in the
387:                 // model/classpath then information will be lost from
388:                 // source files, because the classifier cannot be
389:                 // created on the fly.
390:                 LOG.warn("Modeller.java: a classifier that was in the source"
391: 			 + " file could not be generated in the model "
392: 			 + "(to generate an imported classifier) - "
393: 			 + "information lost",
394: 			 e);
395: 	    }
396: 
397: 
398: 	}
399:     }
