569:     /**
570:        Common code used by addClass and addInterface.
571: 
572:        @param newClassifier Supply one if none is found in the model.
573:        @param name Name of the classifier.
574:        @param modifiers String of modifiers.
575:        @param javadoc The javadoc comment. null or "" if no comment available.
576:        @return The newly created/found classifier.
577:     */
578:     private Object addClassifier(Object newClassifier,
579:                                  String name,
580:                                  short modifiers,
581:                                  String javadoc) {
582:         Object mClassifier;
583:         Object mNamespace;
584: 
585:         if (parseState.getClassifier() != null) {
586:             // the new classifier is a java inner class
587:             mClassifier =
588:         	Model.getFacade().lookupIn(parseState.getClassifier(), name);
589:             mNamespace = parseState.getClassifier();
590:         } else {
591:             // the new classifier is a top level java class
592:             parseState.outerClassifier();
593:             mClassifier = Model.getFacade().lookupIn(currentPackage, name);
594:             mNamespace = currentPackage;
595:         }
596: 
597: 
598:         if (mClassifier == null) {
599:             // if the classifier could not be could in the model
600:             if (LOG.isInfoEnabled()) {
601:                 LOG.info("Created new classifier for " + name);
602:             }
603:             mClassifier = newClassifier;
604:             Model.getCoreHelper().setName(mClassifier, name);
605:             Model.getCoreHelper().setNamespace(mClassifier, mNamespace);
606:         } else {
607:             // it was found and we delete any existing tagged values.
608:             if (LOG.isInfoEnabled()) {
609:                 LOG.info("Found existing classifier for " + name);
610:             }
611:             cleanModelElement(mClassifier);
612:         }
613: 
614:         parseState.innerClassifier(mClassifier);
615: 
616:         // set up the component residency (only for top level classes)
617:         if (parseState.getClassifier() == null) {
618:             // set the clasifier to be a resident in its component:
619:             // (before we push a new parse state on the stack)
620:             
621:             // This test is carried over from a previous implementation,
622:             // but I'm not sure why it would already be set - tfm
623:             if (Model.getFacade().getElementResidences(mClassifier).isEmpty()) {
624:                 Object resident = Model.getCoreFactory()
625:                         .createElementResidence();
626:                 Model.getCoreHelper().setResident(resident, mClassifier);
627:                 Model.getCoreHelper().setContainer(resident,
628:                         parseState.getComponent());
629:             }
630:         }
631: 
632:         // change the parse state to a classifier parse state
633:         parseStateStack.push(parseState);
634:         parseState = new ParseState(parseState, mClassifier, currentPackage);
635: 
636:         setVisibility(mClassifier, modifiers);
637:         addDocumentationTag (mClassifier, javadoc);
638: 
639:         return mClassifier;
640:     }
