701:     /**
702:      * Called from the parser when an operation is
703:      * found.
704:      *
705:      * @param modifiers A sequence of operation modifiers.
706:      * @param returnType The return type of the operation.
707:      * @param name The name of the operation as a string
708:      * @param parameters A number of vectors, each representing a
709:      *
710:      * parameter.
711:      * @param javadoc The javadoc comment. null or "" if no comment available.
712:      * @return The operation.
713:      */
714:     public Object addOperation (short modifiers,
715:                                 String returnType,
716:                                 String name,
717:                                 Vector parameters,
718:                                 String javadoc) {
719: 	Object mOperation = getOperation(name);
720: 	parseState.feature(mOperation);
721: 
722: 	Model.getCoreHelper().setAbstract(mOperation,
723: 				(modifiers & JavaRecognizer.ACC_ABSTRACT) > 0);
724: 	Model.getCoreHelper().setLeaf(mOperation,
725: 			    (modifiers & JavaRecognizer.ACC_FINAL) > 0);
726: 	Model.getCoreHelper().setRoot(mOperation, false);
727: 	setOwnerScope(mOperation, modifiers);
728: 	setVisibility(mOperation, modifiers);
729: 	if ((modifiers & JavaRecognizer.ACC_SYNCHRONIZED) > 0) {
730: 	    Model.getCoreHelper().setConcurrency(mOperation,
731: 	            Model.getConcurrencyKind().getGuarded());
732: 	} else if (Model.getFacade().getConcurrency(mOperation)
733: 		   == Model.getConcurrencyKind().getGuarded()) {
734: 	    Model.getCoreHelper().setConcurrency(mOperation,
735: 	            Model.getConcurrencyKind().getSequential());
736: 	}
737: 
738:         Collection c = new ArrayList(Model.getFacade()
739:                 .getParameters(mOperation));
740: 	for (Iterator i = c.iterator(); i.hasNext();) {
741: 	    Model.getCoreHelper().removeParameter(mOperation, i.next());
742: 	}
743: 
744: 	Object mParameter;
745: 	String typeName;
746: 	Object mClassifier;
747: 
748: 	if (returnType == null
749:             || ("void".equals(returnType)
750:                 && name.equals(Model.getFacade().getName(parseState
751:                         .getClassifier())))) {
752: 	    // Constructor
753: 	    Model.getCoreHelper().addStereotype(mOperation,
754:                 getStereotype(mOperation, "create", "BehavioralFeature"));
755: 	} else {
756: 	    try {
757: 		mClassifier =
758: 		    getContext(returnType).get(getClassifierName(returnType));
759: 
760: 		Object mdl = ProjectManager.getManager()
761: 		    .getCurrentProject().getModel();
762: 		Object voidType = ProjectManager.getManager()
763: 		    .getCurrentProject().findType("void");
764: 		Collection project = ProjectManager.getManager()
765: 		    .getCurrentProject().findFigsForMember(mOperation);
766: 		mParameter = Model.getCoreFactory().buildParameter(
767: 		        mOperation, mdl, voidType, project);
768:                 Model.getCoreHelper().setName(mParameter, "return");
769:                 Model.getCoreHelper().setKind(
770:                         mParameter,
771:                         Model.getDirectionKind().getReturnParameter());
772: 
773:                 Model.getCoreHelper().setType(mParameter, mClassifier);
774: 	    } catch (ClassifierNotFoundException e) {
775: 		// Currently if a classifier cannot be found in the
776:                 // model/classpath then information will be lost from
777:                 // source files, because the classifier cannot be
778:                 // created on the fly.
779:                 LOG.warn("Modeller.java: a classifier that was in the source "
780: 			 + "file could not be generated in the model "
781: 			 + "(for generating operation return type) - "
782: 			 + "information lost",
783: 			 e);
784: 	    }
785: 	}
786: 
787: 	for (Iterator i = parameters.iterator(); i.hasNext();) {
788: 	    Vector parameter = (Vector) i.next();
789: 	    typeName = (String) parameter.elementAt(1);
790: 	    try {
791:                 mClassifier =
792: 		    getContext(typeName).get(getClassifierName(typeName));
793:                 Object mdl = ProjectManager.getManager()
794:                     .getCurrentProject().getModel();
795:                 Object voidType = ProjectManager.getManager()
796:                     .getCurrentProject().findType("void");
797:                 Collection project = ProjectManager.getManager()
798:                     .getCurrentProject().findFigsForMember(mOperation);
799:                 mParameter = Model.getCoreFactory().buildParameter(
800:                         mOperation, mdl, voidType, project);
801: 		Model.getCoreHelper().setName(mParameter,
802: 				    (String) parameter.elementAt(2));
803: 		Model.getCoreHelper().setKind(mParameter,
804:                         Model.getDirectionKind().getInParameter());
805:                 if (Model.getFacade().isAClassifier(mClassifier)) {
806:                     Model.getCoreHelper().setType(mParameter, mClassifier);
807:                 } else {
808:                     // the type resolution failed to find a valid classifier.
809:                     LOG.warn("Modeller.java: a valid type for a parameter "
810: 			     + "could not be resolved:\n "
811: 			     + "In file: " + fileName + ", for operation: "
812: 			     + Model.getFacade().getName(mOperation)
813: 			     + ", for parameter: "
814: 			     + Model.getFacade().getName(mParameter));
815:                 }
816: 	    } catch (ClassifierNotFoundException e) {
817: 		// Currently if a classifier cannot be found in the
818:                 // model/classpath then information will be lost from
819:                 // source files, because the classifier cannot be
820:                 // created on the fly.
821:                 LOG.warn("Modeller.java: a classifier that was in the source "
822: 			 + "file could not be generated in the model "
823: 			 + "(for generating operation params) - "
824: 			 + "information lost",
825: 			 e);
826: 	    }
827: 	}
828: 
829: 	addDocumentationTag (mOperation, javadoc);
830: 
831: 	return mOperation;
832:     }
