651:                 if (tag.equals("header_incl")
652:                         || tag.equals("header_include")) {
653:                     sb.append("#include ");
654:                     sb.append(Model.getFacade().getValueOfTag(tv));
655:                     sb.append(LINE_SEPARATOR);
656:                 }
657:             }
658:         }
659: 
660:         // check if the class has dependencies
661:         {
662:             Collection col = Model.getFacade().getAssociationEnds(cls);
