709:                         else if (generatorPass == HEADER_PASS) {
710:                             // predeclare classes which are not
711:                             // directly used in header usefull for
712:                             // classes which are only used indirectly
713:                             // as pointer where no knowledge about
714:                             // internals of class are needed
715:                             predeclare
716:                                 .append(generateHeaderPackageStart(
717:                                              Model.getFacade().getType(attr)))
718:                                 .append("class ").append(name).append(";")
719:                                     .append(LINE_SEPARATOR);
720:                         }
721:                     }
722:                 }
723:             }
724:         }
