1587:                         || ((publicProtectedPrivate == PROTECTED_PART)
1588:                         && Model.getFacade().isProtected(sf))
1589:                         || ((publicProtectedPrivate == PRIVATE_PART)
1590:                         && Model.getFacade().isPrivate(sf))) {
1591:                     if (!isVisibilityLinePrinted) {
1592:                         isVisibilityLinePrinted = true;
1593:                         sb.append(LINE_SEPARATOR);
1594:                         if (publicProtectedPrivate == PUBLIC_PART) {
1595:                             sb.append(" public:");
1596:                         } else if (publicProtectedPrivate == PROTECTED_PART) {
1597:                             sb.append(" protected:");
1598:                         } else if (publicProtectedPrivate == PRIVATE_PART) {
1599:                             sb.append(" private:");
1600:                         }
1601:                         sb.append(LINE_SEPARATOR);
1602:                     }
1603:                     sb.append(INDENT).append(generate(sf));
1604: 
1605:                     tv = generateTaggedValues(sf, ALL_BUT_DOC_TAGS);
1606:                     if (tv != null && tv.length() > 0) {
1607:                         sb.append(INDENT).append(tv);
1608:                     }
1609:                 }
1610:             }
