1795:     private void generateClassifierBodyTaggedAccess4Attributes(
1796:             Object cls,
1797:             StringBuffer funcPrivate,
1798:             StringBuffer funcProtected,
1799:             StringBuffer funcPublic) {
1800:         Collection strs = Model.getFacade().getAttributes(cls);
