1807:         while (strEnum.hasNext()) {
1808:             Object attr = strEnum.next();
1809:             accessTag = Model.getFacade().getTaggedValueValue(attr, "set");
1810:             if (accessTag != null && accessTag.length() > 0) {
1811:                 if (accessTag.indexOf("public") != -1) {
1812:                     generateSingleAttributeSet(attr, funcPublic);
1813:                 }
1814:                 if (accessTag.indexOf("protected") != -1) {
1815:                     generateSingleAttributeSet(attr, funcProtected);
1816:                 }
1817:                 if (accessTag.indexOf("private") != -1) {
1818:                     generateSingleAttributeSet(attr, funcPrivate);
1819:                 }
1820:             }
1821: 
1822:             accessTag = Model.getFacade().getTaggedValueValue(attr, "get");
1823:             if (accessTag != null && accessTag.length() > 0) {
1824:                 if (accessTag.indexOf("public") != -1) {
1825:                     generateSingleAttributeGet(attr, funcPublic);
1826:                 }
1827:                 if (accessTag.indexOf("protected") != -1) {
1828:                     generateSingleAttributeGet(attr, funcProtected);
1829:                 }
1830:                 if (accessTag.indexOf("private") != -1) {
1831:                     generateSingleAttributeGet(attr, funcPrivate);
1832:                 }
1833:             }
1834:         }
