2085:     private String generateDefaultReturnStatement(Object cls) {
2086:         if (cls == null) return "";
2087: 
2088:         String clsName = Model.getFacade().getName(cls);
2089:         String res = null;
2090:         if (clsName.equals("void")) res = "";
2091:         else if (clsName.equals("char")) res = "return 'x';";
2092:         else if (clsName.equals("int")) res = "return 0;";
2093:         else if (clsName.equals("boolean")) res = "return false;";
2094:         else if (clsName.equals("byte")) res = "return 0;";
2095:         else if (clsName.equals("long")) res = "return 0;";
2096:         else if (clsName.equals("float")) res = "return 0.0;";
2097:         else if (clsName.equals("double")) res = "return 0.0;";
2098: 
2099:         if (res == null) {
2100:             return INDENT + "return 0;" + LINE_SEPARATOR;
2101:         }
2102:         return INDENT + res + LINE_SEPARATOR;
2103:     }
