2105:     private String generateTaggedValues(Object e, int tagSelection) {
2106:         Iterator iter = Model.getFacade().getTaggedValues(e);
2107:         if (!iter.hasNext()) {
2108:             return "";
2109:         }
2110:         StringBuffer buf = new StringBuffer();
2111:         boolean first = true;
2112: 
2113:         String s = null;
2114:         while (iter.hasNext()) {
2115:             s = generateTaggedValue(iter.next(), tagSelection);
2116:             if (s != null && s.length() > 0) {
2117:                 if (first) {
2118:                     /*
2119:                      * Corrected 2001-09-26 STEFFEN ZSCHALER
2120:                      *
2121:                      * Was:
2122:                      buf.append("// {");
2123:                      *
2124:                      * which caused problems with new lines characters
2125:                      * in tagged values (e.g. comments...). The new
2126:                      * version still has some problems with tagged
2127:                      * values containing "*"+"/" as this closes the
2128:                      * comment prematurely, but comments should be
2129:                      * taken out of the tagged values list anyway...
2130:                      */
2131: 
2132:                     if (tagSelection == DOC_COMMENT_TAGS) {
2133:                         // insert main documentation for DocComment at first
2134:                         String doc =
2135:                             (DocumentationManager.hasDocs(e))
2136:                             ? DocumentationManager.getDocs(e, INDENT)
2137:                             : null;
2138:                         if (doc != null && doc.trim().length() > 0) {
2139:                             buf.append(doc.substring(0, doc.indexOf("*/") + 1));
2140:                             buf.append("  ");
2141:                         }
2142:                         else {
2143:                             buf.append("/** ");
2144:                         }
2145:                     }
2146:                     else {
2147:                         buf.append("/* {");
2148:                     }
2149:                     first = false;
2150:                 } // end first
2151:                 else {
2152:                     if (tagSelection == DOC_COMMENT_TAGS) {
2153:                         buf.append(LINE_SEPARATOR)
2154:                             .append(INDENT).append(" *  ");
2155:                     }
2156:                     else {
2157:                         buf.append(", ");
2158:                     }
2159:                 } // end not first tag
2160:                 buf.append(s);
2161:             } // end tag not empty
2162:         } // end while
2163:         /*
2164:          * Corrected 2001-09-26 STEFFEN ZSCHALER
2165:          *
2166:          * Was:
2167:          if (!first) buf.append("}\n");
2168:          *
2169:          * which caused problems with new-lines in tagged values.
2170:          */
2171:         if (!first) {
2172:             if (tagSelection == DOC_COMMENT_TAGS) {
2173:                 buf.append(LINE_SEPARATOR).append(INDENT).append(" */")
2174:                     .append(LINE_SEPARATOR);
2175:             } else {
2176:                 buf.append ("}*/").append(LINE_SEPARATOR);
2177:             }
2178:         }
2179:         else if (tagSelection == DOC_COMMENT_TAGS) {
2180:             // create at least main documentation field, if no other tag found
2181:             String doc = (DocumentationManager.hasDocs(e))
2182:                 ? DocumentationManager.getDocs(e, INDENT)
2183:                 : null;
2184:             if (doc != null && doc.trim().length() > 0) {
2185:                 buf.append(doc).append(LINE_SEPARATOR);
2186:             }
2187:         }
2188: 
2189:         return buf.toString();
2190:     }
