2194:         String s = generateUninterpreted(Model.getFacade().getValueOfTag(tv));
2195: 
2196:         String tagName = Model.getFacade().getTagOfTag(tv);
2197:         if (s == null || s.length() == 0 || s.equals("/** */")
2198:             || (tagName.indexOf("include") != -1)
2199:             || (tagName.indexOf("_incl") != -1)) {
2200:             return "";
2201:         }
2202:         if ((tagSelection == DOC_COMMENT_TAGS)
2203:                 && (isDocCommentTag(tagName))) {
2204:             return generateDocComment4Tag(generateName(tagName)) + s;
2205:         } else if (((tagSelection == ALL_BUT_DOC_TAGS)
2206:                      && (!isDocCommentTag(tagName))
2207:                      && (!tagName.equals("documentation"))
2208:                      && (!tagName.equals("javadocs"))
2209:                     )
2210:                    || (tagSelection == ALL_TAGS)) {
2211:             return tagName + "=" + s;
2212:         } else {
2213:             return "";
2214:         }
2215:     }
