444:         String emailTag = Model.getFacade().getTaggedValueValue(cls, "email");
445:         if (tagTemplatePathName != null && tagTemplatePathName.length() > 0)
446:             templatePathName = tagTemplatePathName;
447:         if (generatorPass == HEADER_PASS) {
