451:         else {
452:             templatePathName = templatePathName + "cpp_template";
453:             fileName = fileName + ".cpp";
454:         }
455:         
456:         File templateFile = new File(templatePathName);
457:         if (templateFile.exists()) {
458:             boolean eof = false;
459:             BufferedReader templateFileReader = null;
460:             try {
