500:     private void replaceToken(StringBuffer line, String tokenName,
501:             String tokenValue) {
502:         int tokenStart;
503:         tokenStart = line.toString().indexOf(tokenName);
504:         if ((tokenStart != -1)
505:             && (tokenValue != null && tokenValue.length() > 0)) {
506:             line.replace(tokenStart,
