879:     private String generateHeaderPackageStart(Object cls) {
880:         StringBuffer sb = new StringBuffer(80);
881: 
882:         if (actualNamespace != null) {
883:             for (Object fromSearch = actualNamespace;
884:                     fromSearch != null;
885:                     fromSearch = getNamespaceWithoutModel(fromSearch)) {
886:                 StringBuffer contPath = new StringBuffer(80);
887:                 Object toSearch = getNamespaceWithoutModel(cls);
888:                 for (; (toSearch != null) && (toSearch != fromSearch);
889:                         toSearch = getNamespaceWithoutModel(toSearch)) {
890:                     contPath.insert(0,
891:                             generateHeaderPackageStartSingle(toSearch));
892:                 }
893:                 if (toSearch == fromSearch) {
894:                     sb.append(contPath.toString());
895:                     break;
896:                 }
897:                 // close one namespace
898:                 sb.append(generateHeaderPackageEndSingle(fromSearch));
899:             }
900:         }
901:         else { // initial start
902:             for (Object toSearch = getNamespaceWithoutModel(cls);
903:                     toSearch != null;
904:                     toSearch = getNamespaceWithoutModel(toSearch)) {
905:                 sb.insert(0, generateHeaderPackageStartSingle(toSearch));
906:             }
907:         }
908:         if (sb.length() > 0) {
909:             sb.insert(0, LINE_SEPARATOR).append(LINE_SEPARATOR);
910:         }
911:         actualNamespace = getNamespaceWithoutModel(cls);
912:         return sb.toString();
913:     }
