1191:     private String generateAttributeParameterModifier(Object attr,
1192:                                                       String def) {
1193:         int modType = getAttributeModifierType(attr);
1194: 
1195: 	// if attr has an abstract type it must be pointer or reference
1196: 	if (modType == NORMAL_MOD || modType == -1) {
1197: 	    Object type = Model.getFacade().getType(attr);
1198: 	    if (type == null) {
1199: 		// model corrupt (this really happened -- aslo)
1200: 		LOG.error(attr + " has no type!");
1201: 		return "";
1202: 	    }
1203: 	    if (Model.getFacade().isAbstract(type)
1204: 		|| Model.getFacade().isAInterface(type)) {
1205: 		if (modType == NORMAL_MOD) {
1206: 		    // user explicitly requested no modifier, print a warning
1207:  		    LOG.warn("Requested no reference or pointer modifier, but");
1208:  		    LOG.warn("\t" + type 
1209:  		            + " cannot be instantiated, using reference");
1210: 		}
1211: 		modType = REFERENCE_MOD;
1212: 	    }
1213: 	}
1214: 
1215:         if (modType == NORMAL_MOD) {
1216:             return "";
1217:         } else if (modType == REFERENCE_MOD) {
1218:             return "&";
1219:         } else if (modType == POINTER_MOD) {
1220:             return "*";
1221:         } else if (def.length() == 0) {
1222:             if (Model.getFacade().isAParameter(attr)
1223:                     && (Model.getFacade().getKind(attr).equals(
1224:                         Model.getDirectionKind().getOutParameter())
1225:                     || Model.getFacade().getKind(attr).equals(
1226:                             Model.getDirectionKind().getInOutParameter()))) {
1227:                 // out or inout parameters are defaulted to reference if
1228:                 // not specified else
1229:                 return "&";
1230:             }
1231:         }
1232:         return def;
1233:     }
