1211:     /**
1212:      * Builds a generalization between a parent and a child. Does not check if
1213:      * multiple inheritance is allowed for the current notation.
1214:      *
1215:      * @param child1 is the child
1216:      * @param parent1 is the parent
1217:      * @return MGeneralization
1218:      */
1219:     public Object buildGeneralization(Object child1, Object parent1) {
1220:         if (!(child1 instanceof MGeneralizableElement)
1221: 	    || !(parent1 instanceof MGeneralizableElement)) {
1222:             throw new IllegalArgumentException();
1223:         }
1224: 
1225:         MGeneralizableElement child = (MGeneralizableElement) child1;
1226:         MGeneralizableElement parent = (MGeneralizableElement) parent1;
1227: 
1228:         if (parent.getParents().contains(child)) {
1229:             return null;
1230:         }
1231:         Iterator it = parent.getGeneralizations().iterator();
1232:         while (it.hasNext()) {
1233:             MGeneralization gen = (MGeneralization) it.next();
1234:             if (gen.getParent().equals(child)) {
1235:                 return null;
1236:             }
1237:         }
1238: 
1239:         if (parent.getNamespace() == null) {
1240:             throw new IllegalArgumentException("parent has no namespace");
1241:         }
1242:         if (parent.isLeaf()) {
1243:             throw new IllegalArgumentException("parent is leaf");
1244:         }
1245:         if (child.isRoot()) {
1246:             throw new IllegalArgumentException("child is root");
1247:         }
1248: 
1249:         MGeneralization gen = (MGeneralization) createGeneralization();
1250:         gen.setParent(parent);
1251:         gen.setChild(child);
1252:         if (parent.getNamespace() != null) {
1253:             gen.setNamespace(parent.getNamespace());
1254:         } else if (child.getNamespace() != null) {
1255:             gen.setNamespace(child.getNamespace());
1256:         }
1257:         return gen;
1258:     }
