844:         MAssociationClass assoc = (MAssociationClass) createAssociationClass();
845:         assoc.setName(cl.getName());
846:         assoc.setAbstract(cl.isAbstract());
847:         assoc.setActive(cl.isActive());
848:         assoc.setAssociationEnds(cl.getAssociationEnds());
849:         assoc.setClassifierRoles(cl.getClassifierRoles());
850:         assoc.setClassifierRoles1(cl.getClassifierRoles1());
851:         assoc.setClassifiersInState(cl.getClassifiersInState());
852:         assoc.setClientDependencies(cl.getClientDependencies());
853:         assoc.setCollaborations(cl.getCollaborations());
