1378:      * @return the parameter
1379:      */
1380:     public Object buildParameter(Object o, Object model, Object voidType,
1381:             Collection propertyChangeListeners) {
1382:         if (o instanceof MEvent) {
1383:             MEvent event = (MEvent) o;
1384:             MParameter res =
1385:                 (MParameter) buildParameter((MModel) model,
1386:                         (MClassifier) voidType);
1387:             res.setKind(MParameterDirectionKind.IN);
1388:             //    removing this next line solves issue 2209
1389:             //res.setNamespace(event.getNamespace());
1390:             event.addParameter(res);
1391:             return res;
