1378:      * @return the parameter
1379:      */
1380:     public Object buildParameter(Object o, Object model, Object voidType,
1381:             Collection propertyChangeListeners) {
1382:         if (o instanceof MEvent) {
1383:             MEvent event = (MEvent) o;
1384:             MParameter res =
1385:                 (MParameter) buildParameter((MModel) model,
1386:                         (MClassifier) voidType);
1387:             res.setKind(MParameterDirectionKind.IN);
1388:             //    removing this next line solves issue 2209
1389:             //res.setNamespace(event.getNamespace());
1390:             event.addParameter(res);
1391:             return res;
1392:         } else if (o instanceof MBehavioralFeature) {
1393:             MBehavioralFeature oper = (MBehavioralFeature) o;
1394:             if (oper == null || oper.getOwner() == null) {
1395:                 throw new IllegalArgumentException(
1396:                         "operation is null or does not have an owner");
1397:             }
1398:             MParameter res =
1399:                 (MParameter) buildParameter((MModel) model,
1400:                         (MClassifier) voidType);
1401:             String name = "arg";
1402:             int counter = 1;
1403: 
1404:             oper.addParameter(res);
1405:             Iterator it = oper.getParameters().iterator();
1406:             while (it.hasNext()) {
1407:                 MParameter para = (MParameter) it.next();
1408:                 if ((name + counter).equals(para.getName())) {
1409:                     counter++;
1410:                 }
1411:             }
1412: 
1413:             res.setName(name + counter);
1414: 
1415:             // we set the listeners to the figs here too
1416:             // it would be better to do that in the figs themselves
1417:             it = propertyChangeListeners.iterator();
1418:             while (it.hasNext()) {
1419:                 PropertyChangeListener listener =
1420:                     (PropertyChangeListener) it.next();
1421:                 // nsmodel.getModelEventPump()
1422:                 //	.removeModelEventListener(listener, res);
1423:                 nsmodel.getModelEventPump()
1424:                 	.addModelEventListener(listener, res);
1425:             }
1426:             return res;
1427:         } else {
1428:             return null;
1429:         }
1430:     }
