166:     /**
167:      * Does the actual adding
168:      * @param listener
169:      * @param modelClass
170:      * @param eventName
171:      */
172:     private synchronized void executeAddClassModelEventListener(MElementListener listener, Class modelClass, String eventName) {
173:         // first register the listener for all elements allready in the model
174:         cat.debug("Registring listener " + listener + " to class " + modelClass.getName() + " and event " + eventName);
175:         Collection col = ModelManagementHelper.getHelper().getAllModelElementsOfKind(modelClass);
176:         MModel root = ProjectManager.getManager().getCurrentProject().getRoot();
177:         if (modelClass.isAssignableFrom(root.getClass())) {
178:             col.add(root);
179:         }
180:         Iterator it = col.iterator();
181:         while (it.hasNext()) {
182:             executeAddModelEventListener(listener, (MBase) it.next(), eventName);
183:         }
184:         // add the class to the 'interested classes list' so the listener is added on creation
185:         // of a modelelement
186:         Set listenerList = (Set) _listenerMapOld.get(modelClass);
187:         if (listenerList == null) {
188:             listenerList = new HashSet();
189:             _listenerMapOld.put(modelClass, listenerList);
190:         }
191:         ListenerEventName couple = new ListenerEventName(listener, eventName);
192:         it = listenerList.iterator();
193:         boolean addNeeded = true;
194:         while (it.hasNext()) {
195:             if (couple.equals(it.next())) {
196:                 return;
197:             }
198:         }
199:         listenerList.add(couple);
200:     }
