410:     synchronized void cleanUp(MBase element) {
411:         String hash = element.hashCode() + "";
412:         Iterator it = _listenerMapOld.keySet().iterator();
413:         List cleanUplist = new ArrayList();
414:         while (it.hasNext()) {
415:             String key = (String) it.next();
