437:     private Set getListenerList(MElementEvent e) {
438:         MBase source = (MBase) e.getSource();
439:         String eventName = e.getName();
440:         if (e.getType() == MElementEvent.ELEMENT_REMOVED)
441:             eventName = REMOVE;
442:         Set listenerList = (Set) _listenerMapOld.get(getKey(source, eventName));
443:         if (_listenerMapOld.get(getKey(source, null)) != null) {
444:             if (listenerList == null)
445:                 listenerList = (Set) _listenerMapOld.get(getKey(source, null));
446:             else
447:                 listenerList.addAll((Set) _listenerMapOld.get(getKey(source, null)));
448:         }
449:         return listenerList != null ? listenerList : new HashSet();
450:     }
