341:     private synchronized void executeAddModelEventListener(MElementListener listener, MBase modelelement, String eventName) {
342:         cat.debug("Registring listener " + listener + " to modelelement " + modelelement + " and event " + eventName);
343:         String key = getKey(modelelement, eventName);
344:         Set listenerList = (Set) _listenerMap.get(key);
345:         if (listenerList == null) {
346:             listenerList = new HashSet();
347:             _listenerMap.put(key, listenerList);
348:         }
349:         listenerList.add(listener);
350:         modelelement.removeMElementListener(this);
351:         modelelement.addMElementListener(this);
