536:      * Returns a set of listenerEventName objects. Each object is a pair of
537:      * a listener that is interested in certain events defined by a given eventname
538:      * This method is called by AbstractUmlFactory when initializing a new
539:      * modelelement.
540:      * @param modelClass
541:      * @return Set
542:      */
543:     Set getInterestedListeners(Class modelClass) {
544:         Set returnSet = new HashSet();
545:         Set interfaces = getInterfaces(modelClass);
546:         Iterator it = interfaces.iterator();
547:         while (it.hasNext()) {
548:             Set listeners = (Set) _listenerMap.get(it.next());
549:             if (listeners != null)
550:                 returnSet.addAll(listeners);
551:         }
552:         return returnSet;
553:     }
554: 
555:     /**
556:      * An utility method to get all interfaces realized by some class, not only
557:      * the interfaces directly realized by the class but also all interfaces
558:      * realized by the interfaces themselves.
559:      * @param modelClass. The class for which we are searching for interfaces
560:      * @return Set the set with all interfaces. It is empty if there are no
561:      * interfaces
562:      */
563:     private Set getInterfaces(Class modelClass) {
564:         Set returnSet = new HashSet();
565:         Class[] interfaces = modelClass.getInterfaces();
566:         for (int i = 0; i < interfaces.length; i++) {
567:             returnSet.add(interfaces[i]);
568:             returnSet.addAll(getInterfaces(interfaces[i]));
569:         }
570:         return returnSet;
571:     }
