579:          */
580:         public ListenerEventName(MElementListener listener, String eventName) {
581:             _eventName = eventName;
582:             _listener = listener;
583:         }
584: 
585:         /**
586:          * Returns the eventName.
587:          * @return String
588:          */
589:         public String getEventName() {
590:             return _eventName;
591:         }
592: 
593:         /**
594:          * Returns the listener.
595:          * @return MElementListener
596:          */
597:         public MElementListener getListener() {
598:             return _listener;
599:         }
600: 
601:         /**
602:          * @see java.lang.Object#equals(java.lang.Object)
603:          */
604:         public boolean equals(Object obj) {
605:             if (obj instanceof ListenerEventName) {
606:                 ListenerEventName couple = (ListenerEventName) obj;
607:                 if (couple.getEventName().equals(_eventName) && couple.getListener().equals(_listener))
608:                     return true;
609:             }
610:             return super.equals(obj);
611:         }
