118: class FigMessageGroup extends FigGroup {
119: 	
120:     /**
121:      * Constructor for FigMessageGroup.
122:      */
123:     public FigMessageGroup() {
124: 	super();
125:     }
126: 
127:     /**
128:      * Constructor for FigMessageGroup.
129:      * @param figs
130:      */
131:     public FigMessageGroup(List figs) {
132:         super(figs);
133:     }
134: 
135:     protected void updateFigPositions() {
136:     	Collection figs = getFigs(null);
137:         Iterator it = figs.iterator();
138:     	if (!figs.isEmpty()) {
139:             FigMessage previousFig = null;
140: 	    for (int i = 0; it.hasNext(); i++) {
141: 		FigMessage fig = (FigMessage) it.next();
142: 		fig.setX(getX());
143: 		if (i != 0) {
144: 		    fig.setY(previousFig.getY()
145: 			     + previousFig.getHeight()
146: 			     + 5);
147: 		} else {
148: 		    fig.setY(getY());
149: 		}
150: 		fig.endTrans();
151:                 previousFig = fig;
152: 	    }
153:     	}
154:     }
155:     
156:     
157: 
158:     /**
159:      * @see org.tigris.gef.presentation.Fig#calcBounds()
160:      */
161:     public void calcBounds() {
162: 	super.calcBounds();
163: 	Collection figs = getFigs(null);
164: 	if (!figs.isEmpty()) {
165: 	    Fig last = null;
166: 	    Fig first = null;
167: 	    // _x = first.getX();
168: 	    // _y = first.getY();
169: 	    _w = 0;
170:             Iterator it = figs.iterator();
171:             int size = figs.size();
172: 	    for (int i = 0; i < size; i++) {
173:                 Fig fig = (Fig) it.next();
174:                 
175:                 if (i == 0) {
176:                     first = fig;
177:                 }
178:                 if (i == size - 1) {
179:                     last = fig;
180:                 }
181:                 
182: 		if (fig.getWidth() > _w) { 
183: 		    _w = fig.getWidth();
184: 		}
185: 	    }
186:             _h = last.getY() + last.getHeight() - first.getY();
187: 	} else {
188: 	    _w = 0;
189: 	    _h = 0;
190: 	}
191:     }
192: 	
193: 	
194: 
195:     /**
196:      * @see org.tigris.gef.presentation.FigGroup#addFig(Fig)
197:      */
198:     public void addFig(Fig f) {
199: 	super.addFig(f);
200: 	updateFigPositions();
201: 	calcBounds();
202:     }
203: 
204: 
205:     /**
206:      * @see org.tigris.gef.presentation.Fig#removeFromDiagram()
207:      */ 
208:     public void delete() { 
209:         Collection figs = getFigs(null);
210:         if (figs != null) {
211:             Iterator it = figs.iterator();
212:             while (it.hasNext()) {
213:                 Fig fig = (Fig) it.next();
214:                 fig.delete();
215:             }
216:         } 
217:         removeAll();
218:         super.delete();
219:     }
220: 
221: 
222:     /**
223:      * @see org.tigris.gef.presentation.Fig#dispose()
224:      */
225:     public void dispose() {
226:     	Collection figs = getFigs(null);
227:         if (figs != null) {
228: 	    Iterator it = figs.iterator();
229: 	    while (it.hasNext()) {
230: 		Fig fig = (Fig) it.next();
231: 		fig.dispose();
232: 	    }
233:         }
234:         removeAll();
235:         super.dispose();
236:     }
237: 
238: }
