61: /**
62:  * Class to display a UML comment in a diagram.
63:  *
64:  * @author Andreas Rueckert
65:  */
66: public class FigComment
67:     extends FigNodeModelElement
68:     implements VetoableChangeListener,
69: 	       DelayedVChangeListener,
70: 	       MouseListener,
71: 	       KeyListener,
72: 	       PropertyChangeListener {
73:     /**
74:      * Logger.
75:      */
76:     private static final Logger LOG = Logger.getLogger(FigComment.class);
77: 
78:     ////////////////////////////////////////////////////////////////
79:     // constants
80: 
81:     private int x = 0;
82:     private int y = 0;
83:     private int width = 80;
84:     private int height = 60;
85:     private int dogear = 10; // a dog-ear = a bent corner in a book
86: 
87:     private boolean readyToEdit = true;
88: 
89:     ////////////////////////////////////////////////////////////////
90:     // instance variables
91: 
92:     // The figure that holds the text of the note.
93:     private FigText text;
94: 
95:     private FigPoly body;
96:     private FigPoly urCorner; // the upper right corner
97:     
98:     /**
99:      * Flag to indicate that we have just been created. This is to fix the
100:      * problem with loading comments that have stereotypes already
101:      * defined.<p>
102:      */
103:     private boolean newlyCreated = false;
104: 
105:     ////////////////////////////////////////////////////////////////
106:     // constructors
107: 
108:     /**
109:      * The main constructor used for file loading.
110:      */
111:     public FigComment() {
112: 
113:         body = new FigPoly(Color.black, Color.white);
114:         body.addPoint(x, y);
115:         body.addPoint(x + width - 1 - dogear, y);
116:         body.addPoint(x + width - 1, y + dogear);
117:         body.addPoint(x + width - 1, y + height - 1);
118:         body.addPoint(x, y + height - 1);
119:         body.addPoint(x, y);
120:         body.setFilled(true);
121:         body.setLineWidth(1);
122: 
123:         urCorner = new FigPoly(Color.black, Color.white);
124:         urCorner.addPoint(x + width - 1 - dogear, y);
125:         urCorner.addPoint(x + width - 1, y + dogear);
126:         urCorner.addPoint(x + width - 1 - dogear, y + dogear);
127:         urCorner.addPoint(x + width - 1 - dogear, y);
128:         urCorner.setFilled(true);
129:         Color col = body.getFillColor();
130:         urCorner.setFillColor(col.darker());
131:         urCorner.setLineWidth(1);
132: 
133:         if (SingleStereotypeEnabler.isEnabled()) {
134:             getStereotypeFig().setHeight(STEREOHEIGHT);
135:             getStereotypeFig().setVisible(false);
136:         }
137:         
138:         setBigPort(new FigRect(x, y, width, height, null, null));
139:         getBigPort().setFilled(false);
140:         getBigPort().setLineWidth(0);
141: 
142:         text = new FigMultiLineText(x + 2, y + 2, width - 2 - dogear, height - 4, true);
143: 
144:         // add Figs to the FigNode in back-to-front order
145:         addFig(getBigPort());
146:         addFig(body);
147:         addFig(urCorner);
148:         addFig(getStereotypeFig());
149:         addFig(text);
150: 
151:         setBlinkPorts(false); //make port invisble unless mouse enters
152:         Rectangle r = getBounds();
153:         setBounds(r.x, r.y, r.width, r.height);
154:         updateEdges();
155: 
156:         readyToEdit = false;
157:         // Mark this as newly created. This is to get round the problem with
158:         // creating figs for loaded comments that had stereotypes. They are
159:         // saved with their dimensions INCLUDING the stereotype, but since we
160:         // pretend the stereotype is not visible, we add height the first time
161:         // we render such a comment. This is a complete fudge, and really we
162:         // ought to address how comment objects with stereotypes are saved. But
163:         // that will be hard work.
164:         newlyCreated = true;
165:     }
166: 
167:     /**
168:      * Construct a new comment.
169:      *
170:      * @param gm the graphmodel
171:      * @param node the underlying UML Comment
172:      */
173:     public FigComment(GraphModel gm, Object node) {
174:         this();
175:         setOwner(node);
176:     }
177: 
178:     /**
179:      * Get the default text for this figure.
180:      *
181:      * @return The default text for this figure.
182:      */
183:     public String placeString() {
184:         String placeString = retrieveNote();
185:         if (placeString == null) {
186:             placeString = "new note";
187:         }
188:         return placeString;
189:     }
190: 
191:     /**
192:      * Clone this figure.
193:      *
194:      * @return The cloned figure.
195:      */
196:     public Object clone() {
197:         FigComment figClone = (FigComment) super.clone();
198:         Iterator thisIter = this.getFigs().iterator();
199:         while (thisIter.hasNext()) {
200:             Object thisFig = thisIter.next();
201:             if (thisFig == body) {
202:                 figClone.body = (FigPoly) thisFig;
203:             }
204:             if (thisFig == urCorner) {
205:                 figClone.urCorner = (FigPoly) thisFig;
206:             }
207:             if (thisFig == text) {
208:                 figClone.text = (FigText) thisFig;
209:             }
210:         }
211:         return figClone;
212:     }
213: 
214:     ////////////////////////////////////////////////////////////////
215:     // event handlers
216: 
217:     /**
218:      * See FigNodeModelElement.java for more info on these methods.
219:      */
220: 
221:     /**
222:      * If the user double clicks on any part of this FigNode, pass it
223:      * down to one of the internal Figs.  This allows the user to
224:      * initiate direct text editing.
225:      *
226:      * @see java.awt.event.MouseListener#mouseClicked(java.awt.event.MouseEvent)
227:      */
228:     public void mouseClicked(MouseEvent me) {
229:         if (!readyToEdit) {
230:             if (Model.getFacade().isAModelElement(getOwner())) {
231:                 readyToEdit = true;
232:             } else {
233:                 LOG.debug("not ready to edit note");
234:                 return;
235:             }
236:         }
237:         if (me.isConsumed()) {
238:             return;
239:         }
240:         if (me.getClickCount() >= 2
241: 	    && !(me.isPopupTrigger()
242: 		 || me.getModifiers() == InputEvent.BUTTON3_MASK)) {
243:             if (getOwner() == null) {
244:                 return;
245:             }
246:             Fig f = hitFig(new Rectangle(me.getX() - 2, me.getY() - 2, 4, 4));
247:             if (f instanceof MouseListener) {
248:                 ((MouseListener) f).mouseClicked(me);
249:             }
250:         }
251:         me.consume();
252:     }
253: 
254:     /**
255:      * @see java.beans.VetoableChangeListener#vetoableChange(java.beans.PropertyChangeEvent)
256:      */
257:     public void vetoableChange(PropertyChangeEvent pce) {
258:         Object src = pce.getSource();
