668:                 calcBounds();
669:             }
670:         } else {
671:             getStereotypeFig().setOwner(getOwner());
672: 
673:             if (!getStereotypeFig().isVisible()) {
674:                 getStereotypeFig().setVisible(true);
675: 
676:                 // Only adjust the stereotype height if we are not newly
677:                 // created. This gets round the problem of loading classes with
678:                 // stereotypes defined, which have the height already including
679:                 // the stereotype.
680: 
681:                 if (!newlyCreated) {
