474:     public Dimension getMinimumSize() {
475: 
476:         // Get the size of the text field.
477:         Dimension aSize = text.getMinimumSize();
478: 
479:         // If we have a stereotype displayed, then allow some space for that
480:         // (width and height)
481: 
482:         if (getStereotypeFig().isVisible()) {
483:             Dimension stereoMin = getStereotypeFig().getMinimumSize();
484:             aSize.width =
485:                 Math.max(aSize.width,
486:                          stereoMin.width);
487:             if (SingleStereotypeEnabler.isEnabled()) {
488:                 aSize.height += STEREOHEIGHT;
489:             } else {
490:                 aSize.height += stereoMin.height;
491:             }
492:         }
493:         
494:         // And add the gaps around the textfield to get the minimum
495:         // size of the note.
