228:     public void mouseClicked(MouseEvent me) {
229:         if (!readyToEdit) {
230:             if (Model.getFacade().isAModelElement(getOwner())) {
231:                 readyToEdit = true;
232:             } else {
233:                 LOG.debug("not ready to edit note");
234:                 return;
235:             }
236:         }
237:         if (me.isConsumed()) {
238:             return;
239:         }
240:         if (me.getClickCount() >= 2
241: 	    && !(me.isPopupTrigger()
242: 		 || me.getModifiers() == InputEvent.BUTTON3_MASK)) {
243:             if (getOwner() == null) {
244:                 return;
245:             }
246:             Fig f = hitFig(new Rectangle(me.getX() - 2, me.getY() - 2, 4, 4));
