279:     /**
280:      * @see java.beans.PropertyChangeListener#propertyChange(java.beans.PropertyChangeEvent)
281:      */
282:     public void propertyChange(PropertyChangeEvent pve) {
283:         Object src = pve.getSource();
284:         String pName = pve.getPropertyName();
285:         if (pName.equals("editing")
286: 	    && Boolean.FALSE.equals(pve.getNewValue())) {
287:             //parse the text that was edited
288:             textEdited((FigText) src);
289:             // resize the FigNode to accomodate the new text
290:             Rectangle bbox = getBounds();
291:             Dimension minSize = getMinimumSize();
292:             bbox.width = Math.max(bbox.width, minSize.width);
293:             bbox.height = Math.max(bbox.height, minSize.height);
294:             setBounds(bbox.x, bbox.y, bbox.width, bbox.height);
295:             endTrans();
296:         } else {
297:             super.propertyChange(pve);
298:         }
299:     }
