292:     /**
293:      * initialize the menu for diagram construction in the explorer popup menu.
294:      *
295:      */
296:     private void initMenuCreateModelElements() {
297: 	List targets = TargetManager.getInstance().getTargets();
298:         List actions = new ArrayList();
299: 	if (targets.size() >= 2) {
300: 	    // Check to see if all targets are classifiers
301: 	    // before adding an option to create an association between
302: 	    // them all
303: 	    boolean classifiersOnly = true;
304: 	    for (Iterator it = targets.iterator();
305: 	            it.hasNext() && classifiersOnly; ) {
306: 		if (!Model.getFacade().isAClassifier(it.next())) {
307: 		    classifiersOnly = false;
308: 		}
309: 	    }
310:             if (classifiersOnly) {
311:                 actions.add(new ActionCreateAssociation(
312:                 	Model.getMetaTypes().getAssociation(), 
313:                 	targets));
314:             }
315: 	}
316: 	if (targets.size() == 2) {
317:             addCreateModelElementAction(
318:         	    actions,
319:         	    Model.getMetaTypes().getDependency());
320:             addCreateModelElementAction(
321:         	    actions,
322:         	    Model.getMetaTypes().getGeneralization());
323: 	}
324: 	if (actions.size() == 1) {
325: 	    add((Action) actions.get(0));
326: 	} else if (actions.size() > 1) {
327: 	    JMenu menu = new JMenu("Create Model Element");
328: 	    add(menu);
329: 	    for (Iterator it = actions.iterator(); it.hasNext(); ) {
330:                 menu.add((Action) it.next());
331: 	    }
332: 	}
333:     }
334:     
335:     private void addCreateModelElementAction(
336: 	        Collection menuItems,
337: 		Object metaType) {
338: 	List targets = TargetManager.getInstance().getTargets();
339: 	Object source = targets.get(0);
340: 	Object dest = targets.get(1);
341: 	if (Model.getUmlFactory().isConnectionValid(
342: 		    metaType, source, dest)) {
343: 	    menuItems.add(new ActionCreateModelElement(metaType, source, dest));
344: 	}
345:     }
