347:     /**
348:      * Locale a popup menu item in the navigator pane.
349:      *
350:      * @param key
351:      *            The key for the string to localize.
352:      * @return The localized string.
353:      */
354:     private String menuLocalize(String key) {
355:         return Translator.localize(key);
356:     }
