412:     private class ActionAddExistingRelatedNode extends ActionAddExistingNode {
413: 
414:         /**
415:          * The UML object to be added to the diagram.
416:          */
417:         private Object object;
418: 
419:         /**
420:          * The Constructor.
421:          *
422:          * @param name the localized name of the action
423:          * @param o the node UML object to be added
424:          */
425:         public ActionAddExistingRelatedNode(String name, Object o) {
426:             super(name, o);
427:             object = o;
428:         }
429: 
430:         /**
431:          * @see javax.swing.Action#isEnabled()
432:          */
433:         public boolean isEnabled() {
434:             ArgoDiagram dia = ProjectManager.getManager().
435:                 getCurrentProject().getActiveDiagram();
436:             if (dia == null) return false;
437:             MutableGraphModel gm = (MutableGraphModel) dia.getGraphModel();
438:             return gm.canAddNode(object);
439:         }
440:     } /* end class ActionAddExistingRelatedNode */
