442:     private class ActionCreateModelElement extends AbstractAction {
443: 	
444: 	private Object metaType; 
445: 	private Object source; 
446: 	private Object dest;
447: 	
448: 	private final Logger LOG =
449: 	    Logger.getLogger(ActionCreateModelElement.class);
450: 	
451: 	public ActionCreateModelElement(
452: 		Object metaType, 
453: 		Object source, 
454: 		Object dest) {
455: 	    super("Create " + Model.getMetaTypes().getName(metaType));
456: 	    this.metaType = metaType;
457: 	    this.source = source;
458: 	    this.dest = dest;
459: 	}
460: 
461: 	public void actionPerformed(ActionEvent e) {
462:             try {
463: 		Model.getUmlFactory().buildConnection(
464: 		    metaType,
465: 		    source,
466: 		    null,
467: 		    dest,
468: 		    null,
469: 		    null,
470: 		    null);
471: 	    } catch (IllegalModelElementConnectionException e1) {
472: 		LOG.error("Exception", e1);
473: 	    }
474: 	}
475:     }
476:     
477:     private class ActionCreateAssociation extends AbstractAction {
478: 	
479: 	private Object metaType; 
480: 	private List classifiers;
481: 	
482: 	private final Logger LOG =
483: 	    Logger.getLogger(ActionCreateModelElement.class);
484: 	
485: 	public ActionCreateAssociation(
486: 		Object metaType, 
487: 		List classifiers) {
488: 	    super("Create " + Model.getMetaTypes().getName(metaType));
489: 	    this.metaType = metaType;
490: 	    this.classifiers = classifiers;
491: 	}
492: 
493: 	public void actionPerformed(ActionEvent e) {
494:             try {
495: 		Object newElement = Model.getUmlFactory().buildConnection(
496: 		    metaType,
497: 		    classifiers.get(0),
498: 		    null,
499: 		    classifiers.get(1),
500: 		    null,
501: 		    null,
502: 		    null);
503: 		for (int i = 2; i < classifiers.size(); ++i) {
504:                     Model.getUmlFactory().buildConnection(
505: 			    Model.getMetaTypes().getAssociationEnd(),
506: 			    newElement,
507: 			    null,
508: 			    classifiers.get(i),
509: 			    null,
510: 			    null,
511: 			    null);
512: 		}
513: 	    } catch (IllegalModelElementConnectionException e1) {
514: 		LOG.error("Exception", e1);
515: 	    }
516: 	}
517:     }
518: }
