353:     /**
354:      * Get the FigNode that the fig id represents.
355:      *
356:      * @param figId (In the form Figx.y.z)
357:      * @return the FigNode with the given id
358:      */
359:     private FigNode getFigNode(String figId) {
360:         if (figId.indexOf('.') < 0) {
361:             // If there is no dot then this must be a top level Fig and can be
362:             // assumed to be a FigNode.
363:             Fig f = findFig(figId);
364:             if (f instanceof FigNode) {
365:                 return (FigNode) f;
366:             } else {
367:                 throw new IllegalStateException("FigID " + figId
368:                         + " is not a node");
369:             }
370:         }
371:         // If the id does not look like a top-level Fig then we can assume that
372:         // this is an id of a FigEdgePort inside some FigEdge.
373:         // So extract the FigEdgePort from the FigEdge and return that as
374:         // the FigNode.
375:         figId = figId.substring(0, figId.indexOf('.'));
376:         FigEdgeModelElement edge = (FigEdgeModelElement) findFig(figId);
377:         if (edge == null) {
378:             throw new IllegalStateException(
379:                     "Can't find a FigNode with id " + figId);
380:         }
381:         edge.makeEdgePort();
382:         return edge.getEdgePort();
383:     }
