58: /**
59:  * The results tab for the find dialog.
60:  *
61:  */
62: public class TabResults
63:         extends AbstractArgoJPanel
64:         implements
65:                 Runnable,
66:                 MouseListener,
67:                 ActionListener,
68:                 ListSelectionListener,
69:                 KeyListener {
70:     private static final Logger LOG = Logger.getLogger(TabResults.class);
71: 
72:     private static int numJumpToRelated = 0;
73: 
74:     /** Insets in pixels  */
75:     private static final int INSET_PX = 3;
76: 
77:     ////////////////////////////////////////////////////////////////
78:     // instance variables
79:     private PredicateFind pred;
80:     private ChildGenerator cg = null;
81:     private Object root = null;
82:     private JSplitPane mainPane;
83:     private Vector results = new Vector();
84:     private Vector related = new Vector();
85:     private Vector diagrams = new Vector();
86:     private boolean relatedShown = false;
87: 
88:     private JLabel resultsLabel = new JLabel(/*"Results:"*/);
89:     private JTable resultsTable;
90:     private TMResults resultsModel;
91: 
92:     private JLabel relatedLabel = new JLabel(/*"Related Elements:"*/);
93:     private JTable relatedTable = new JTable(4, 4);
94:     private TMResults relatedModel = new TMResults();
95: 
96:     /**
97:      * The constructor.
98:      *
99:      */
100:     public TabResults() {
101: 	this(true);
102:     }
103: 
104:     /**
105:      * The constructor.
106:      *
107:      * @param showRelated true if related results should be shown
108:      */
109:     public TabResults(boolean showRelated) {
110: 	super("Results", true);
111: 	relatedShown = showRelated;
112: 	setLayout(new BorderLayout());
113: 	resultsTable = new JTable(10, showRelated ? 4 : 3);
114: 	resultsModel = new TMResults(showRelated);
115: 
116: 	JPanel resultsW = new JPanel();
117: 	JScrollPane resultsSP = new JScrollPane(resultsTable);
118: 	resultsW.setLayout(new BorderLayout());
119: 	resultsLabel.setBorder(BorderFactory.createEmptyBorder(
120:                 INSET_PX, INSET_PX, INSET_PX, INSET_PX));
121: 	resultsW.add(resultsLabel, BorderLayout.NORTH);
122: 	resultsW.add(resultsSP, BorderLayout.CENTER);
123: 	resultsTable.setModel(resultsModel);
124: 	resultsTable.addMouseListener(this);
125: 	resultsTable.addKeyListener(this);
126: 	resultsTable.getSelectionModel().addListSelectionListener(
127: 								   this);
128: 	resultsTable.setSelectionMode(
129: 				       ListSelectionModel.SINGLE_SELECTION);
130: 	resultsW.setMinimumSize(new Dimension(100, 100));
131: 
132: 	JPanel relatedW = new JPanel();
133: 	if (relatedShown) {
134: 	    JScrollPane relatedSP = new JScrollPane(relatedTable);
135: 	    relatedW.setLayout(new BorderLayout());
136:             relatedLabel.setBorder(BorderFactory.createEmptyBorder(
137:                     INSET_PX, INSET_PX, INSET_PX, INSET_PX));
138: 	    relatedW.add(relatedLabel, BorderLayout.NORTH);
139: 	    relatedW.add(relatedSP, BorderLayout.CENTER);
140: 	    relatedTable.setModel(relatedModel);
141: 	    relatedTable.addMouseListener(this);
142: 	    relatedTable.addKeyListener(this);
143: 	    relatedW.setMinimumSize(new Dimension(100, 100));
144: 	}
145: 
146: 	if (relatedShown) {
147: 	    mainPane =
148: 		new JSplitPane(JSplitPane.VERTICAL_SPLIT,
149: 			       resultsW,
150: 			       relatedW);
151: 	    add(mainPane, BorderLayout.CENTER);
152: 	} else {
153: 	    add(resultsW, BorderLayout.CENTER);
154: 	}
155: 
156:     }
157: 
158:     ////////////////////////////////////////////////////////////////
159:     // accessors
160: 
161:     /**
162:      * @param p the predicate for the search
163:      */
164:     public void setPredicate(PredicateFind p) {
165: 	pred = p;
166:     }
167: 
168:     /**
169:      * @param r the root object for the search
170:      */
171:     public void setRoot(Object r) {
172: 	root = r;
173:     }
174: 
175:     /**
176:      * @param gen the generator
177:      */
178:     public void setGenerator(ChildGenerator gen) {
179: 	cg = gen;
180:     }
181: 
182:     /**
183:      * @param res the results
184:      * @param dia the diagrams
185:      */
186:     public void setResults(Vector res, Vector dia) {
187: 	results = res;
188: 	diagrams = dia;
189: 	Object[] msgArgs = {new Integer(results.size()) };
190: 	resultsLabel.setText(Translator.messageFormat(
191:             "dialog.tabresults.results-items", msgArgs));
192: 	resultsModel.setTarget(results, diagrams);
193: 	relatedModel.setTarget(null, null);
194: 	relatedLabel.setText(
195:             Translator.localize("dialog.tabresults.related-items"));
196:     }
197: 
198:     /**
199:      * @see org.argouml.ui.AbstractArgoJPanel#spawn()
200:      */
201:     public AbstractArgoJPanel spawn() {
202: 	TabResults newPanel = (TabResults) super.spawn();
203: 	if (newPanel != null) {
204: 	    newPanel.setResults(results, diagrams);
205: 	}
206: 	return newPanel;
207:     }
208: 
209:     /**
210:      * Handle a doubleclick on the results tab.
211:      */
212:     public void doDoubleClick() {
213: 	myDoubleClick(resultsTable);
214:     }
215: 
216:     /**
217:      * Select the result at the given index.
218:      *
219:      * @param index the given index
220:      */
221:     public void selectResult(int index) {
222: 	if (index < resultsTable.getRowCount()) {
223: 	    resultsTable.getSelectionModel().setSelectionInterval(index,
224: 								   index);
225: 	}
226:     }
227: 
