238:     // MouseListener implementation
239: 
240:     /**
241:      * @see java.awt.event.MouseListener#mousePressed(java.awt.event.MouseEvent)
242:      */
243:     public void mousePressed(MouseEvent me) {
244:     }
245: 
246:     /**
247:      * @see java.awt.event.MouseListener#mouseReleased(java.awt.event.MouseEvent)
248:      */
249:     public void mouseReleased(MouseEvent me) {
250:     }
251: 
252:     /**
253:      * @see java.awt.event.MouseListener#mouseClicked(java.awt.event.MouseEvent)
254:      */
255:     public void mouseClicked(MouseEvent me) {
256: 	if (me.getClickCount() >= 2)
257: 	    myDoubleClick(me.getSource());
258:     }
259: 
260:     /**
261:      * @see java.awt.event.MouseListener#mouseEntered(java.awt.event.MouseEvent)
262:      */
263:     public void mouseEntered(MouseEvent me) {
264:     }
265: 
