273:     /**
274:      * @see java.beans.PropertyChangeListener#propertyChange(java.beans.PropertyChangeEvent)
275:      */
276:     public void propertyChange(PropertyChangeEvent pve) {
277:         Object src = pve.getSource();
278:         String pName = pve.getPropertyName();
279:         if (pName.equals("editing")
280: 	    && Boolean.FALSE.equals(pve.getNewValue())) {
281:             //parse the text that was edited
282:             textEdited((FigText) src);
283:             // resize the FigNode to accomodate the new text
284:             Rectangle bbox = getBounds();
285:             Dimension minSize = getMinimumSize();
286:             bbox.width = Math.max(bbox.width, minSize.width);
287:             bbox.height = Math.max(bbox.height, minSize.height);
288:             setBounds(bbox.x, bbox.y, bbox.width, bbox.height);
289:             endTrans();
290:         } else {
291:             super.propertyChange(pve);
292:         }
293:     }
