300:             if (Model.getFacade().isAModelElement(getOwner())) {
301:                 storeNote("");
302:                 readyToEdit = true;
303:             } else {
304:                 LOG.debug("not ready to edit note");
305:                 return;
306:             }
307:         }
308:         if (ke.isConsumed()) {
309:             return;
310:         }
311:         if (getOwner() == null) {
312:             return;
313:         }
314:         bodyTextFig.keyPressed(ke);
315:     }
