463:     /**
464:      * Get the minimum size for the note figure.
465:      *
466:      * @return The minimum size for the note figure.
467:      */
468:     public Dimension getMinimumSize() {
469: 
470:         // Get the size of the text field.
471:         Dimension aSize = bodyTextFig.getMinimumSize();
472: 
473:         // If we have a stereotype displayed, then allow some space for that
474:         // (width and height)
475: 
476:         if (getStereotypeFig().isVisible()) {
477:             Dimension stereoMin = getStereotypeFig().getMinimumSize();
478:             aSize.width =
479:                 Math.max(aSize.width,
480:                          stereoMin.width);
481:             aSize.height += stereoMin.height;
482:         }
483:         
484:         // And add the gaps around the textfield to get the minimum
485:         // size of the note.
486:         return new Dimension(aSize.width + 4 + dogear,
487: 			     aSize.height + 4);
488:     }
