215:     /**
216:      * If the user double clicks on any part of this FigNode, pass it
217:      * down to one of the internal Figs.  This allows the user to
218:      * initiate direct text editing.
219:      *
220:      * @see java.awt.event.MouseListener#mouseClicked(java.awt.event.MouseEvent)
221:      */
222:     public void mouseClicked(MouseEvent me) {
223:         if (!readyToEdit) {
224:             if (Model.getFacade().isAModelElement(getOwner())) {
225:                 readyToEdit = true;
226:             } else {
227:                 LOG.debug("not ready to edit note");
228:                 return;
229:             }
230:         }
231:         if (me.isConsumed()) {
232:             return;
233:         }
234:         if (me.getClickCount() >= 2
235: 	    && !(me.isPopupTrigger()
236: 		 || me.getModifiers() == InputEvent.BUTTON3_MASK)) {
237:             if (getOwner() == null) {
238:                 return;
239:             }
240:             Fig f = hitFig(new Rectangle(me.getX() - 2, me.getY() - 2, 4, 4));
241:             if (f instanceof MouseListener) {
242:                 ((MouseListener) f).mouseClicked(me);
243:             }
244:         }
245:         me.consume();
246:     }
