37: 
38: /**
39:  * @author Bob Tarling
40:  */
41: public class FigStereotypesCompartment extends FigCompartment {
42:     
43:     String keyword;
44:     
45:     /**
46:      * The constructor.
47:      *
48:      * @param x x
49:      * @param y y
50:      * @param w width
51:      * @param h height
52:      */
53:     public FigStereotypesCompartment(int x, int y, int w, int h) {
54:         super(x, y, w, h);
55:     }
56: 
57:     /**
58:      * @see org.argouml.uml.diagram.ui.FigFeaturesCompartment#populate()
59:      */
60:     public void populate() {
61:         
62:         int acounter = 1;
63:         Object modelElement = getGroup().getOwner();
64:         Fig bigPort = this.getBigPort();
65:         int xpos = bigPort.getX();
66:         int ypos = bigPort.getY();
67: 
68:         List figs = getFigs();
69:         CompartmentFigText stereotypeTextFig;
70:         
71:         if (keyword != null) {
72:             if (figs.size() <= acounter) {
73:                 stereotypeTextFig =
74:                     new FigFeature(
75:                             xpos + 1,
76:                             ypos + 1
77:                             + (acounter - 1)
78:                                 * FigNodeModelElement.ROWHEIGHT,
79:                             0,
80:                             FigNodeModelElement.ROWHEIGHT - 2,
81:                             bigPort);
82:                 // bounds not relevant here
83:                 stereotypeTextFig.setJustification(FigText.JUSTIFY_CENTER);
84:                 addFig(stereotypeTextFig);
85:             } else {
86:                 stereotypeTextFig =
87:                     (CompartmentFigText) figs.get(acounter);
88:             }
89:             stereotypeTextFig.setText(
90:                     Notation.generate((NotationContext) getGroup(),
91:                             keyword));
92:             acounter++;
93:         }
94:         
95:         Collection stereos = Model.getFacade().getStereotypes(modelElement);
96:         if (stereos != null) {
97:             Iterator iter = stereos.iterator();
98:             while (iter.hasNext()) {
99:                 Object stereotype = iter.next();
100:                 if (figs.size() <= acounter) {
101:                     stereotypeTextFig =
102:                         new FigFeature(
103:                                 xpos + 1,
104:                                 ypos + 1
105:                                 + (acounter - 1)
106:                                 	* FigNodeModelElement.ROWHEIGHT,
107:                                 0,
108:                                 FigNodeModelElement.ROWHEIGHT - 2,
109:                                 bigPort);
110:                     // bounds not relevant here
111:                     stereotypeTextFig.setJustification(FigText.JUSTIFY_CENTER);
112:                     addFig(stereotypeTextFig);
113:                 } else {
114:                     stereotypeTextFig =
115:                         (CompartmentFigText) figs.get(acounter);
116:                 }
117:                 stereotypeTextFig.setText(
118:                         Notation.generate((NotationContext) getGroup(),
119:                         stereotype));
120:                 stereotypeTextFig.setOwner(stereotype); //TODO: update the model again here?
121:                 /* This causes another event, and modelChanged() called,
122:                  * and updateAttributes() called again...
123:                  */
124: 
125:                 acounter++;
126:             }
127:             if (figs.size() > acounter) {
128:                 //cleanup of unused FigText's
129:                 for (int i = figs.size() - 1; i >= acounter; i--) {
130:                     removeFig((Fig) figs.get(i));
131:                 }
132:             }
133:         }
134:     }
135:     
136:     /**
137:      * Allows a parent Fig to specify some stereotype text to display that is
138:      * not actually contained by its owner.
139:      * An example of this usage is to display <<interface>> as a stereotype
140:      * on FigInterface.
141:      * @param stereotype the text of the pseudo stereotype
142:      */
143:     public void setPseudoSereotype(String stereotype) {
144:         keyword = stereotype;
145:     }
146: }
