41: /**
42:  * The model for a list that Mbases contains. The state of the MBase is still 
43:  * kept in the Mbase itself. This list is only to be used as the model for some 
44:  * GUI element like UMLLinkedList 
45:  * @since Oct 2, 2002
46:  * @author jaap.branderhorst@xs4all.nl
47:  */
48: public abstract class UMLModelElementListModel2
49:     extends DefaultListModel
50:     implements TargetListener, MElementListener {
51: 
52:     private String _eventName = null;
53:     protected Object _target = null;
54: 
55:     /**
56:      * Flag to indicate wether list events should be fired
57:      */
58:     protected boolean _fireListEvents = true;
