60:     /**
61:      * Flag to indicate wether the model is being build
62:      */
63:     protected boolean _buildingModel = false;
64: 
65:     /**
66:      * Constructor for UMLModelElementListModel2.
67:      */
68:     public UMLModelElementListModel2(String eventName) {
69:         super();
70:         setEventName(eventName);
71:     }
72: 
73:     /**
74:      * Constructor to be used if the subclass does not depend on the 
75:      * MELementListener methods and setTarget method implemented in this
76:      * class.
77:      */
78:     public UMLModelElementListModel2() {
79:         super();
80:     }
81: 
82:     /**
83:      * @see ru.novosoft.uml.MElementListener#listRoleItemSet(
84:      *          ru.novosoft.uml.MElementEvent)
85:      */
86:     public void listRoleItemSet(MElementEvent e) { }
87: 
88:     /**
89:      * @see ru.novosoft.uml.MElementListener#propertySet(
90:      *          ru.novosoft.uml.MElementEvent)
91:      */
92:     public void propertySet(MElementEvent e) {
93:         if (isValidEvent(e)) {
94:             removeAllElements();
95:             _buildingModel = true;
96:             buildModelList();
97:             _buildingModel = false;
98:             if (getSize() > 0) {
99:                 fireIntervalAdded(this, 0, getSize() - 1);
100:             }
101:         }
102:     }
103: 
104:     /**
105:      * @see ru.novosoft.uml.MElementListener#recovered(
106:      *          ru.novosoft.uml.MElementEvent)
107:      */
108:     public void recovered(MElementEvent e) { }
109: 
