111:      * @see ru.novosoft.uml.MElementListener#removed(
112:      *          ru.novosoft.uml.MElementEvent)
113:      */
114:     public void removed(MElementEvent e) { }
115: 
116:     /**
117:      * @see ru.novosoft.uml.MElementListener#roleAdded(
118:      *          ru.novosoft.uml.MElementEvent)
119:      */
120:     public void roleAdded(MElementEvent e) {
121:         if (isValidEvent(e)) {
122:             Object o = getChangedElement(e);
123:             if (o instanceof Collection) {
124:                 Iterator it = ((Collection) o).iterator();
125:                 while (it.hasNext()) {
126:                     Object o2 = it.next();
127:                     addElement(it.next());
128:                 }
129:             } else {
130:                 addElement(o);
131:             }
132:         }
133:     }
134: 
135:     /**
136:      * @see ru.novosoft.uml.MElementListener#roleRemoved(
137:      *          ru.novosoft.uml.MElementEvent)
138:      */
139:     public void roleRemoved(MElementEvent e) {
140:         boolean valid = false;
141:         if (!(getChangedElement(e) instanceof Collection)) {
142:             valid = contains(getChangedElement(e));
143:         } else {
144:             Collection col = (Collection) getChangedElement(e);
145:             Iterator it = col.iterator();
146:             valid = true;
147:             while (it.hasNext()) {
148:                 Object o = it.next();
149:                 if (!contains(o)) {
150:                     valid = false;
151:                     break;
152:                 }
153:             }
154:         }
155:         if (valid) {
156:             Object o = getChangedElement(e);
157:             if (o instanceof Collection) {
158:                 Iterator it = ((Collection) o).iterator();
159:                 while (it.hasNext()) {
160:                     removeElement(it.next());
161:                 }
162:             } else {
163:                 removeElement(o);
164:             }
165:         }
166:     }
