168:     /**
169:      * Builds the list of elements. Called from targetChanged every time the 
170:      * target of the proppanel is changed. 
171:      */
172:     protected abstract void buildModelList();
173: 
174:     /**
175:      * Utility method to set the elements of this list to the contents of the
176:      * given collection.
177:      * @param col
178:      */
179:     protected void setAllElements(Collection col) {
180:         if (!isEmpty())
181:             removeAllElements();
182:         addAll(col);
183:     }
184: 
185:     /**
186:      * Utility method to add a collection of elements to the model
187:      * @param col
188:      */
189:     protected void addAll(Collection col) {
190:         Iterator it = col.iterator();
191:         _fireListEvents = false;
192:         int oldSize = getSize();
193:         while (it.hasNext()) {
194:             Object o = it.next();
195:             addElement(o);
196:         }
197:         _fireListEvents = true;
198:         fireIntervalAdded(this, oldSize - 1, getSize() - 1);
199:     }
200: 
201:     /**
202:      * Utility method to get the target. Sets the _target if the _target is null
203:      * via the method setTarget().
204:      * @return MModelElement
205:      */
206:     protected Object getTarget() {
207:         return _target;
208:     }
209: 
210:     /**
211:      * Utility method to get the changed element from some event e
212:      * @param e
213:      * @return Object
214:      */
215:     protected Object getChangedElement(MElementEvent e) {
216:         if (e.getAddedValue() != null)
217:             return e.getAddedValue();
218:         if (e.getRemovedValue() != null)
219:             return e.getRemovedValue();
220:         if (e.getNewValue() != null)
221:             return e.getNewValue();
222:         return null;
223:     }
