225:     /**
226:      * @see javax.swing.DefaultListModel#contains(java.lang.Object)
227:      */
228:     public boolean contains(Object elem) {
229:         if (super.contains(elem))
230:             return true;
231:         if (elem instanceof Collection) {
232:             Iterator it = ((Collection) elem).iterator();
233:             while (it.hasNext()) {
234:                 if (!super.contains(it.next())) {
235:                     return false;
236:                 }
237:             }
238:             return true;
239:         }
240:         return false;
241:     }
242: 
243:     /**
244:      * Sets the target. If the old target is instanceof MBase, it also removes
245:      * the model from the element listener list of the target. If the new target
246:      * is instanceof MBase, the model is added as element listener to the new 
247:      * target.
248:      * @param theNewTarget
249:      */
250:     public void setTarget(Object theNewTarget) {
251:         theNewTarget = theNewTarget instanceof Fig ? ((Fig) theNewTarget).getOwner() : theNewTarget;
252:         if (ModelFacade.isABase(theNewTarget) || ModelFacade.isADiagram(theNewTarget)) {
253:             if (ModelFacade.isABase(_target)) {
254:                 UmlModelEventPump.getPump()
255: 		    .removeModelEventListener(this,
256: 					      /*(MBase)*/_target,
257: 					      _eventName);
258:             }
259: 
260:             if (ModelFacade.isABase(theNewTarget)) {
261:                 _target = theNewTarget;
262:                 // UmlModelEventPump.getPump()
263:                 // .removeModelEventListener(this, (MBase)_target,
264:                 // _eventName);
265:                 UmlModelEventPump.getPump()
266: 		    .addModelEventListener(this,
267: 					   /*(MBase)*/_target,
268: 					   _eventName);
269: 
270:                 removeAllElements();
271:                 _buildingModel = true;
272:                 buildModelList();
273:                 _buildingModel = false;
274:                 if (getSize() > 0) {
275:                     fireIntervalAdded(this, 0, getSize() - 1);
276:                 }
277:             } else {
278:                 _target = null;
279:                 removeAllElements();
280:             }
281: 
282:         }
283:     }
284: 
285:     /**
286:      * Returns true if the given element is valid, i.e. it may be added to the 
287:      * list of elements.
288:      *
289:      * @param element
290:      */
291:     protected abstract boolean isValidElement(Object/*MBase*/ element);
292: 
293:     /**
294:      * Returns true if some event is valid. An event is valid if the
295:      * element changed in the event is valid. This is determined via a
296:      * call to isValidElement.  This method can be overriden by
297:      * subclasses if they cannot determine if it is a valid event just
298:      * by checking the changed element.
299:      *
300:      * @param e
301:      * @return boolean
302:      */
303:     protected boolean isValidEvent(MElementEvent e) {
304:         boolean valid = false;
305:         if (!(getChangedElement(e) instanceof Collection)) {
306:             valid = isValidElement(/*(MBase)*/getChangedElement(e));
307:             if (!valid && e.getNewValue() == null && e.getOldValue() != null) {
308:                 valid = true; // we tried to remove a value
309:             }
310:         } else {
311:             Collection col = (Collection) getChangedElement(e);
312:             Iterator it = col.iterator();
313:             if (!col.isEmpty()) {
314:                 valid = true;
315:                 while (it.hasNext()) {
316:                     Object o = it.next();
317:                     if (!isValidElement(/*(MBase)*/o)) {
318:                         valid = false;
319:                         break;
320:                     }
321:                 }
322:             } else {
323:                 if (e.getOldValue() instanceof Collection
324:                     && !((Collection) e.getOldValue()).isEmpty()) {
325:                     valid = true;
326:                 }
327:             }
328:         }
329:         return valid;
330:     }
