36: public class ClClassName implements Clarifier {
37:   public static ClClassName TheInstance = new ClClassName();
38:   public static int WAVE_LENGTH = 4;
39:   public static int WAVE_HEIGHT = 2;
40: 
41:   ////////////////////////////////////////////////////////////////
42:   // instance variables
43:   Fig _fig;
44: 
45:   public void setFig(Fig f) { _fig = f; }
46:   public void setToDoItem(ToDoItem i) { }
47: 
48:   public void paintIcon(Component c, Graphics g, int x, int y) {
49:     if (_fig instanceof FigNodeModelElement) {
50:       FigNodeModelElement fnme = (FigNodeModelElement) _fig;
51:       FigText ft = fnme.getNameFig();
52:       int left  = ft.getX() + 10;
53:       int height = ft.getY() + ft.getHeight() - 7;
54:       int right = ft.getX() + ft.getWidth() - 10;
55:       g.setColor(Color.red);
56:       int i = left;
57:       while (true) {
58: 	g.drawLine(i, height, i + WAVE_LENGTH, height + WAVE_HEIGHT);
59: 	i += WAVE_LENGTH;
60: 	if (i >= right) break;
61: 	g.drawLine(i, height + WAVE_HEIGHT, i + WAVE_LENGTH, height);
62: 	i += WAVE_LENGTH;
63: 	if (i >= right) break;
64: 	g.drawLine(i, height, i + WAVE_LENGTH, height + WAVE_HEIGHT/2);
65: 	i += WAVE_LENGTH;
66: 	if (i >= right) break;
67: 	g.drawLine(i, height + WAVE_HEIGHT/2, i + WAVE_LENGTH, height);
68: 	i += WAVE_LENGTH;
69: 	if (i >= right) break;
70:       }
71:       _fig = null;
72:     }
73:   }
74: 
75:   public int getIconWidth() { return 0; }
76:   public int getIconHeight() { return 0; }
77: 
78:   public boolean hit(int x, int y) {
79:     FigNodeModelElement fc = (FigNodeModelElement) _fig;
80:     FigText ft = fc.getNameFig();
81:     boolean res = ft.contains(x, y);
82:     _fig = null;
83:     return res;
84:   }
85: 
86: } /* end class ClClassName */
