167:      * Constructor.
168:      */
169:     public Project() {
170:         profile = new ProfileJava();
171:         projectSettings = new ProjectSettings();
172:         
173:         Model.getModelManagementFactory().setRootModel(null);
174: 
175:         authorname = Configuration.getString(Argo.KEY_USER_FULLNAME);
176:         authoremail = Configuration.getString(Argo.KEY_USER_EMAIL);
177:         description = "";
178:         // this should be moved to a ui action.
179:         version = ArgoVersion.getVersion();
180: 
181:         searchpath = new Vector();
182:         members = new MemberList();
183:         historyFile = "";
184:         models = new Vector();
185:         diagrams = new Vector();
186:         cgPrefs = new GenerationPreferences();
187:         defaultModelTypeCache = new HashMap();
188: 
189:         LOG.info("making empty project with empty model");
190:         try {
191:             // Jaap Branderhorst 2002-12-09
192:             // load the default model
193:             // this is NOT the way how it should be since this makes argo
194:             // depend on Java even more.
195:             setDefaultModel(profile.getProfileModel());
196:         } catch (ProfileException e) {
197:             // TODO: how are we going to handle exceptions here?
198:             // I think we need a ProjectException.
199:             LOG.error("Exception setting the default profile", e);
200:         }
201:         addSearchPath("PROJECT_DIR");
202:         TargetManager.getInstance().addTargetListener(this);
203:     }
204: 
205:     /**
206:      * Find the base name of this project.<p>
207:      *
208:      * This is the name minus any valid file extension.
209:      *
210:      * @return The name (a String).
211:      */
212:     public String getBaseName() {
213:         String n = getName();
214:         n = PersistenceManager.getInstance().getBaseName(n);
215:         return n;
