328:     /**
329:      * @param d the diagram
330:      */
331:     private void addDiagramMember(ArgoDiagram d) {
332:         ProjectMember pm = new ProjectMemberDiagram(d, this);
333:         addDiagram(d);
334:         // if diagram added successfully, add the member too
335:         members.add(pm);
336:     }
337: 
338:     /**
339:      * @param pm the member to be added
340:      */
341:     private void addTodoMember(ProjectMemberTodoList pm) {
342:         // Adding a todo member removes any existing one.
343:         members.add(pm);
344:         LOG.info("Added todo member, there are now " + members.size());
345:     }
346: 
347:     /**
348:      * @param m the member to be added
349:      */
350:     public void addMember(Object m) {
351: 
352:         if (m == null) {
353:             throw new IllegalArgumentException(
354:                     "A model member must be suppleid");
355:         } else if (m instanceof ArgoDiagram) {
356:             LOG.info("Adding diagram member");
357:             addDiagramMember((ArgoDiagram) m);
358:         } else if (m instanceof ProjectMemberTodoList) {
359:             LOG.info("Adding todo member");
360:             addTodoMember((ProjectMemberTodoList) m);
361:         } else if (Model.getFacade().isAModel(m)) {
362:             LOG.info("Adding model member");
363:             addModelMember(m);
364:         } else {
365:             throw new IllegalArgumentException(
366:                     "The member must be a UML model todo member or diagram."
367:                     + "It is " + m.getClass().getName());
368:         }
369:         LOG.info("There are now " + members.size() + " members");
370:     }
371: 
372:     /**
373:      * @param m the model
374:      */
375:     private void addModelMember(Object m) {
376: 
377:         boolean memberFound = false;
378:         Object currentMember =
379:             members.getMember(ProjectMemberModel.class);
380:         if (currentMember != null) {
381:             Object currentModel =
382:                 ((ProjectMemberModel) currentMember).getModel();
383:             if (currentModel == m) {
384:                 memberFound = true;
385:             }
386:         }
387: 
388:         if (!memberFound) {
389:             if (!models.contains(m)) {
390:                 addModel(m);
391:             }
392:             // got past the veto, add the member
393:             ProjectMember pm = new ProjectMemberModel(m, this);
394:             LOG.info("Adding model member to start of member list");
395:             members.add(pm);
396:         } else {
397:             LOG.info("Attempted to load 2 models");
398:             throw new IllegalArgumentException(
399:                     "Attempted to load 2 models");
400:         }
401:     }
402: 
403:     /**
404:      * @param model a namespace
405:      */
406:     public void addModel(Object model) {
407: 
408:         if (!Model.getFacade().isANamespace(model)) {
409:             throw new IllegalArgumentException();
410: 	}
411: 
412:         // fire indeterminate change to avoid copying vector
413:         if (!models.contains(model)) {
414:             models.addElement(model);
415:         }
416:         setCurrentNamespace(model);
417:         ProjectManager.getManager().setSaveEnabled(true);
418:     }
419: 
420:     /**
421:      * Removes a project member diagram completely from the project.
422:      * @param d the ArgoDiagram
423:      */
424:     protected void removeProjectMemberDiagram(ArgoDiagram d) {
425:         if (activeDiagram == d) {
426:             ArgoDiagram defaultDiagram;
427:             if (diagrams.size() == 1) {
428:                 // We're deleting the last diagram so lets create a new one
429:                 // TODO: Once we go MDI we won't need this.
430:                 Object treeRoot = 
431:                     Model.getModelManagementFactory().getRootModel();
432:                 defaultDiagram =
433:                     DiagramFactory.getInstance()
434:                         .createDiagram(UMLClassDiagram.class, treeRoot, null);
435:                 addMember(defaultDiagram);
436:             } else {
437:                 // Make the topmost diagram (that is not the one being deleted)
438:                 // current.
439:                 defaultDiagram = (ArgoDiagram) diagrams.get(0);
440:                 if (defaultDiagram == d) {
441:                     defaultDiagram = (ArgoDiagram) diagrams.get(1);
442:                 }
443:             }
444:             activeDiagram = defaultDiagram;
445:             TargetManager.getInstance().setTarget(defaultDiagram);
446:         }
447: 
448:         removeDiagram(d);
449:         members.remove(d);
450:         d.remove();
451:         ProjectManager.getManager().setSaveEnabled(true);
452:     }
