657:      */
658:     public Collection findAllPresentationsFor(Object obj) {
659:         Collection figs = new ArrayList();
660:         Iterator it = diagrams.iterator();
661:         while (it.hasNext()) {
662:             Diagram diagram = (Diagram) it.next();
663:             Fig aFig = diagram.presentationFor(obj);
