744:     /**
745:      * Finds a diagram with a specific name or UID.
746:      *
747:      * @return the diagram object (if found). Otherwize null.
748:      * @param name is the name to search for.
749:      */
750:     public ArgoDiagram getDiagram(String name) {
751:         Iterator it = diagrams.iterator();
752:         while (it.hasNext()) {
753:             ArgoDiagram ad = (ArgoDiagram) it.next();
754:             if (ad.getName() != null && ad.getName().equals(name)) {
755:                 return ad;
756:             }
757:             if (ad.getItemUID() != null
