159:         public void showPopupMenu(MouseEvent me) {
160: 
161:             if (getLastSelectedPathComponent() == null) {
162:                 return;
163: 	    }
164: 
165:             Object selectedItem =
166:                 ((DefaultMutableTreeNode) getLastSelectedPathComponent())
167:                         .getUserObject();
