30: /** This class models the designer who is building a complex design in
31:  *  some application domain and needs continuous feedback to aid in the
32:  *  making of good design decisions. */
33: 
34: public class Designer implements Poster, Runnable, java.io.Serializable {
35:   ////////////////////////////////////////////////////////////////
36:   // instance variables
37: 
38:   public static Designer TheDesigner = new Designer();
39: 
40:   /** ToDoList items that are on the designers ToDoList because of
41:    *  this material. */
42:   private ToDoList _toDoList;
43: 
44:   /** Preferences -- very ill defined */
45:   private Properties _prefs;
46: 
47:   /** The email address where other designers can send this designer
48:    * email. This is not used yet. */
49:   private String _emailAddr;
50: 
51:   /** The decisions currently being considered by the designer.
52:    *  Decisions are currently modeled as simple descriptive strings.
53:    *  Each decision also has a priority number which is ill defined,
54:    *  but positive Ints mean that the designer is considering it. This
55:    *  explicit representation of what decisions the designer is
56:    *  interested in at a given moment allows the Agency to select
57:    *  relevant critics for execution. */
58: 
59:   private DecisionModel _decisions;
60: 
61:   /** The goals of the designer are likewise used by the Agency to
62:    *  determine what critics are relevant. */
63: 
64:   private GoalModel _goals;
65: 
66:   /** Each designer has their own Agency instance that is responsible
67:    *  for selecting and executing critics that are relevant to thid
68:    *  designer on an on going basis. */
69: 
70:   private Agency _agency;
71: 
72:   private Thread _critiquer;
73:   private int _critiquingInterval = 3000;
74:   private boolean _autoCritique = true;
75: 
76:   private ChildGenerator _cg = new ChildGenDMElements();
77:   //needs-more-work: theInstance()
78: 
79:   private static Object _CritiquingRoot;
80: 
81:   ////////////////////////////////////////////////////////////////
82:   // constructor and singeton methods
83: 
84:   public Designer() {
85:     _decisions = new DecisionModel();
86:     _goals = new GoalModel();
87:     _agency = new Agency();
88:     _prefs = new Properties();
89:     _toDoList = new ToDoList();
90:     _toDoList.spawnValidityChecker(this);
91:     _emailAddr = "jrobbins@ics.uci.edu";
92:     TheDesigner = this;
93:   }
94: 
95:   public static void theDesigner(Designer d) { TheDesigner = d; }
96:   public static Designer theDesigner() { return TheDesigner; }
97: 
98: 
99:   ////////////////////////////////////////////////////////////////
100:   // critiquing
101: 
102:   /** Start a separate thread to continually select and execute
103:    *  critics that are relevant to this designer's work. */
104:   public void spawnCritiquer(Object root) {
105:     /* needs-more-work really should be a separate class */
106:     _critiquer = new Thread(this, "CritiquingThread");
107:     _critiquer.setDaemon(true);
108:     _critiquer.start();
109:     _CritiquingRoot = root;
110:   }
111: 
112:   /** Continuously select and execute critics against this designer's
113:    *  design. spawnCritiquer is used to start a Thread that runs
114:    *  this. */
115:   public void run() {
116:     Vector alreadyCritiqued = new Vector();       // jer added 970911
117:     Vector toCritique = new Vector();     // jer added 970911
118:     while (true) {
119:       if (_CritiquingRoot != null && getAutoCritique()) {
120:         synchronized (_CritiquingRoot) {
121:           _agency.determineActiveCritics(this);
122:           // jer added 970911
123:           // now use ChildGenerators instead of elements()
124:           //- _CritiquingRoot.critique(this);
125:           alreadyCritiqued.removeAllElements();
126:           toCritique.removeAllElements();
127:           toCritique.addElement(_CritiquingRoot);
128:           while (toCritique.size() > 0) {
129:             Object dm = toCritique.elementAt(toCritique.size()-1);
130:             toCritique.removeElement(dm);
131:             if (!alreadyCritiqued.contains(dm)) {
132:               alreadyCritiqued.addElement(dm);
133:               Agency.applyAllCritics(dm, theDesigner());
134:               Enumeration subDMs = _cg.gen(dm);
135:               while (subDMs.hasMoreElements())
136:                 toCritique.addElement(subDMs.nextElement());
137:             }
138:           }
139:         }
140:       }
141:       // needs-more-work: limit % CPU time used
142:       try { _critiquer.sleep(getCritiquingInterval()); }
143:       catch (InterruptedException ignore) {
144:         System.out.println("InterruptedException!!!");
145:       }
146:     }
147:   }
148: 
149: 
150:   /** Look for potential problems or open issues in the given design. */
151:   public void critique(Design des) { des.critique(this); }
152: 
153:   ////////////////////////////////////////////////////////////////
154:   // criticism control
155: 
156:   /** Ask this designer's agency to select which critics should be active. */
157:   public void determineActiveCritics() {
158:     _agency.determineActiveCritics(this);
159:   }
160: 
161:   ////////////////////////////////////////////////////////////////
162:   // accessors
163: 
164:   /** autoCritique and critiquingInterval are two prameters that
165:    *  control how the critiquing thread operates. If autoCritique is
166:    *  false then now critiquing is done in the background. The
167:    *  critiquingInterval determines how often the critiquing thread
168:    *  executes. The concept of an interval between runs will become
169:    *  less important as Argo is redesigned to be more trigger
170:    *  driven. */
171: 
172:   public boolean getAutoCritique() { return _autoCritique; }
173:   public void setAutoCritique(boolean b) { _autoCritique = b; }
174:   public int getCritiquingInterval() { return _critiquingInterval; }
175:   public void setCritiquingInterval(int i) { _critiquingInterval = i; }
176: 
177:    public static void setCritiquingRoot(Object d) {
178:      synchronized (_CritiquingRoot) {
179:        _CritiquingRoot = d;
180:        theDesigner()._toDoList.removeAllElements();
181:      }
182:    }
183:    public static Object getCritiquingRoot() { return _CritiquingRoot; }
184: 
185:    public ChildGenerator getChildGenerator() { return _cg; }
186:    public void setChildGenerator(ChildGenerator cg) { _cg = cg; }
187: 
188:   public DecisionModel getDecisionModel() { return _decisions; }
189:   public Vector getDecisions() { return _decisions.getDecisions(); }
190:   public GoalModel getGoalModel() { return _goals; }
191:   public Vector getGoals() { return _goals.getGoals(); }
192:   //public SkillsModel getSkillsModel() { return _skills; }
193: 
194:   /** ToDoItem's that are posted by the designer are assumed to be
195:    *  valid until the designer explicitly removes them. Perhaps in the
196:    *  future the designer could specify a condition to determine when
197:    *  his items expire.
198:    * @see ToDoItem
199:    * @see Critic#stillValid
200:    */
201:   public boolean stillValid(ToDoItem i, Designer d) { return true; }
202: 
203:   public static Vector UNSPEC_DECISION_VECTOR = null;
204:   public static Vector UNSPEC_GOAL_VECTOR = null;
205:   static {
206:       UNSPEC_DECISION_VECTOR = new Vector();
207:       UNSPEC_DECISION_VECTOR.addElement(Decision.UNSPEC);
208:       UNSPEC_GOAL_VECTOR = new Vector();
209:       UNSPEC_GOAL_VECTOR.addElement(Goal.UNSPEC);
210:   }  
211:   public boolean supports(Decision d) { return d == Decision.UNSPEC; }
212:   public Vector getSupportedDecisions() { return UNSPEC_DECISION_VECTOR; }
213: 
214:   public boolean supports(Goal g) { return true; }
215:   public Vector getSupportedGoals() { return UNSPEC_GOAL_VECTOR; }
216: 
217:   public boolean containsKnowledgeType(int type) { return true; }
218:   public Vector getSupportedKnowledgeType() {
219:     //needs-more-work
220:     return null;
221:   }
222: 
223: 
224:   /** Reply this Designer's ToDoList, a list of pending problems and
225:    *  issues that the designer might be interested in.
226:    * @see ToDoList */
227:   public ToDoList getToDoList() {
228:     return _toDoList;
229:   }
230: 
231:   /** Add all the items in the given list to my list. */
232:   public void addToDoItems(ToDoList list) {
233:     _toDoList.addAll(list);
234:   }
235: 
236:   /** Remove all the items in the given list from my list. */
237:   public void removeToDoItems(ToDoList list) {
238:     _toDoList.removeAll(list);
239:   }
240: 
241:   /** Reply the designers personal preferneces. */
242:   public Properties getPrefs() {
243:     return _prefs;
244:   }
245: 
246:   /** Reply true iff the designer is currently considering the given
247:    *  decison. */
248:   public boolean isConsidering(String decision) {
249:     return _decisions.isConsidering(decision);
250:   }
251: 
252:   public boolean isConsidering(Decision d) {
253:     return d.getPriority() > 0;
254:   }
255: 
256:   /** Record the extent to which the designer is considering the given
257:    *  decision. */
258:   public void setDecisionPriority(String decision, int priority) {
259:     _decisions.setDecisionPriority(decision, priority);
260:   }
261: 
262:   public void defineDecision(String decision, int priority) {
263:     _decisions.defineDecision(decision, priority);
264:   }
265: 
266:   public void startConsidering(String decision) {
267:     _decisions.startConsidering(decision);
268:   }
269: 
270:   public void startConsidering(Decision d) {
271:     _decisions.startConsidering(d);
272:   }
273: 
274:   public void stopConsidering(String decision) {
275:     _decisions.stopConsidering(decision);
276:   }
277: 
278:   public void stopConsidering(Decision d) {
279:     _decisions.stopConsidering(d);
280:   }
281: 
282:   /** Record the extent to which the designer desires the given goal. */
283:   public boolean hasGoal(String goal) { return _goals.hasGoal(goal); }
284: 
285:   public void setGoalPriority(String goal, int priority) {
286:     _goals.setGoalPriority(goal, priority);
287:   }
288: 
289: //   public Object getGoalInfo(String goal){
290: //     return _goals.getGoalInfo(goal);
291: //   }
292: 
293: //   public void setGoalInfo(String goal, String info) {
294: //     _goals.setGoalInfo(goal, info);
295: //   }
296: 
297:   public void startDesiring(String goal) { _goals.startDesiring(goal); }
298:   public void stopDesiring(String goal) { _goals.stopDesiring(goal); }
299:   public String getExpertEmail() { return _emailAddr; }
300:   public void setExpertEmail(String addr) { _emailAddr = addr; }
301:   public void hush() { /* do nothing */ }
302:   public void unhush() { /* do nothing */ }
303: 
304:   /** Reply the Agency object that is helping this Designer. */
305:   public Agency getAgency() { return _agency; }
306: 
307:   ////////////////////////////////////////////////////////////////
308:   // user interface
309: 
310:   /** Inform the human designer using this system that the given
311:    * ToDoItem should be considered. This can be disruptive if the item
312:    * is urgent, or (more commonly) it is added to his ToDoList so that
313:    * he can consider it at his leisure. */
314:   public void inform(ToDoItem item) {
315:     if (item.getPriority() >= disruptiveThreshold())
316:       disruptivelyWarn(item);
317:     else
318:       nondisruptivelyWarn(item);
319:   }
320: 
321:   /** Inform the human designer that there is an urgent ToDoItem that
322:    *  (s)he must consider before doing any more work.  Currently not
323:    *  implemented. */
324:   public synchronized void disruptivelyWarn(ToDoItem item) {
325:     // open a window or do something with item
326:   }
327: 
328:   /** Inform the human designer that there is a ToDoItem that is
329:    *  relevant to his design work, and allow him to consider it on his
330:    *  own initiative. */
331:   public synchronized void nondisruptivelyWarn(ToDoItem item) {
332:     _toDoList.addElement(item);
333:   }
334: 
335:   /** Used to determine which ToDoItems are urgent. */
336:   public int disruptiveThreshold() {
337:     // needs-more-work: check prefs
338:     return 9;
339:   }
340: 
341:   public String toString() {
342:     String printString = super.toString() + " [\n";
343:     printString += "  " + "decisions: " + _decisions.toString() + "\n";
344:     printString += "  " + "goals: " + _goals.toString() + "\n";
345:     printString += "  " + "prefs: " + _prefs.toString() + "\n";
346:     printString += "  " + "to do: " + _toDoList.toString() + "\n";
347:     printString += "]\n";
348:     return printString;
349:   }
350: 
351:   ////////////////////////////////////////////////////////////////
352:   // issie resolution
353: 
354:   public void fixIt(ToDoItem item, Object arg) { }
355:   public boolean canFixIt(ToDoItem item) { return false; }
356: 
357: } /* end class Designer */
