73:     java.util.StringTokenizer st = new java.util.StringTokenizer(s, "\n\r");
74:     List newAttrs = new ArrayList();
75:     while (st.hasMoreTokens()) {
76:       String token = st.nextToken();
77:       MAttribute attr = parseAttribute(token);
78:       newAttrs.add(attr);
79:     }
80:     // System.out.println("parsed " + newAttrs.size() + " attributes");
81: 	Vector features = new Vector(cls.getFeatures());
82: 	Vector oldAttrs = new Vector(MMUtil.SINGLETON.getAttributes(cls));
83: 	features.removeAll(oldAttrs);
84: 
85: 	// don't forget to remove old Attrbutes!
86: 	for (int i = 0; i < oldAttrs.size(); i++)
87: 		((MAttribute)oldAttrs.elementAt(i)).remove();
88: 	features.removeAll(MMUtil.SINGLETON.getAttributes(cls));
89: 	features.addAll(newAttrs);
90: 	cls.setFeatures(features);
91: 	
92:   }
