95:    *  [visibility] [keywords] returntype name(params)[;] */
96:   public MOperation parseOperation(String s) {
97:     s = s.trim();
98:     if (s.endsWith(";")) s = s.substring(0, s.length()-1);
99:     MOperation res = new MOperationImpl();
100:     s = parseOutVisibility(res, s);
101:     s = parseOutKeywords(res, s);
102:     s = parseOutReturnType(res, s);
103:     s = parseOutName(res, s);
104:     s = parseOutParams(res, s);
105:     s = s.trim();
106:     if (s.length() > 2)
107:       System.out.println("leftover in parseOperation=|" + s + "|");
108:     return res;
109:   }
