344:   /** Parse a line of the form: "name: trigger [guard] / actions" */
345:   public MTransition parseTransition(String s) {
346:     // strip any trailing semi-colons
347:     s = s.trim();
348:     if (s.length() == 0) return null;
349:     if (s.charAt(s.length()-1) == ';')
350:       s = s.substring(0, s.length() - 2);
351: 
352:     String name = "";
353:     String trigger = "";
354:     String guard = "";
355:     String actions = "";
356:     if (s.indexOf(":", 0) > -1) {
357:       name = s.substring(0, s.indexOf(":")).trim();
358:       s = s.substring(s.indexOf(":") + 1).trim();
359:     }
360: 
361:     if (s.indexOf("[", 0) > -1 && s.indexOf("]", 0) > -1) {
362:       guard = s.substring(s.indexOf("[", 0)+1, s.indexOf("]")).trim();
363:       s = s.substring(0, s.indexOf("[")) + s.substring(s.indexOf("]")+1);
364:       s = s.trim();
365:     }
366: 
367:     if (s.indexOf("/", 0) > -1) {
368:       actions = s.substring(s.indexOf("/")+1).trim();
369:       s = s.substring(0, s.indexOf("/")).trim();
370:     }
371: 
372:     trigger = s;
373: 
374: //     System.out.println("name=|" + name +"|");
375: //     System.out.println("trigger=|" + trigger +"|");
376: //     System.out.println("guard=|" + guard +"|");
377: //     System.out.println("actions=|" + actions +"|");
378: 
379:     MTransition t = new MTransitionImpl();
380:     t.setName(parseName(name));
381: 
382:     t.setTrigger(parseEvent(trigger));
383:     t.setGuard(parseGuard(guard));
384:     t.setEffect(parseActions(actions));
385: 
386: 
387:     return t;
388:   }
