648:       if (!(o instanceof Diagram)) continue; 
649:       if (o instanceof MModel) continue; 
650:       Diagram d = (Diagram) o; 
651:       model = d.getGraphModel();  
652:       if (!(model instanceof DeploymentDiagramGraphModel)) continue; 
653:         
654:       Vector nodes = model.getNodes(); 
655:       int si = nodes.size(); 
656:       for (int j=0; j<si; j++) { 
657:         MModelElement node = (MModelElement) nodes.elementAt(j); 
658:         if (node != null && (node instanceof MComponentImpl)) { 
659:           MComponent mcomp = (MComponent) node; 
660:           if (mcomp.getNamespace() != coi.getNamespace()) continue;
661:           String comp_name = mcomp.getName(); 
662:           if (comp_name != null && (comp_name.equals(base))) { 
663:             v.addElement(mcomp); 
664:             coi.setClassifiers(v); 
665:             return;  
666:           }       
667:         } 
668:       } 
669:     } 
670:     co.setName(base);     
671:     v.addElement(co); 
672:     coi.setClassifiers(v);
673:     coi.setName(new String(name)); 
674:  
675:   } 
