47:     public UMLComboBoxEntry(Object/*MModelElement*/ modelElement, Profile profile, boolean isPhantom) {
48:         _element = modelElement;
49:         if (modelElement != null) {
50:             Object/*MNamespace*/ ns = ModelFacade.getNamespace(modelElement);
51:             _shortName = profile.formatElement(modelElement, ns);
52:         }
53:         else {
54:             _shortName = "";
