148:     public Object/*MModelElement*/ getElement(Object targetModel) {
149:         //
150:         //  if phantom then
151:         //    we need to possibly recreate the package structure
152:         //       in the target model
153:         if (_isPhantom && targetModel != null) {
154:             Object/*MNamespace*/ targetNS = findNamespace(ModelFacade.getNamespace(_element), targetModel);
155:             Object/*MModelElement*/ clone = null;
156:             try {
157:                 clone = _element.getClass().getConstructor(new Class[] {}).newInstance(new Object[] {});
158:                 ModelFacade.setName(clone, ModelFacade.getName(_element));
159:                 Object stereo = null;
160:                 if (ModelFacade.getStereotypes(_element).size() > 0) {
161:                     stereo = ModelFacade.getStereotypes(_element).iterator().next();
162:                 }
163:                 ModelFacade.setStereotype(clone, stereo);
164:                 if (ModelFacade.isAStereotype(clone)) {
165:                     ModelFacade.setBaseClass(clone, ModelFacade.getBaseClass(_element));
166:                 }
167:                 ModelFacade.addOwnedElement(targetNS, clone);
168:                 _element = clone;
169:             }
170:             catch (Exception ex) {
171:                 ex.printStackTrace();
172:             }
173:             _isPhantom = false;
174:         }
175:         return _element;
176:     }
177: 
