61:     public FigMessage(Object owner) {
62:         super();
63:         textGroup = new FigTextGroup();
64:         textGroup.addFig(getNameFig());
65:         textGroup.addFig(getStereotypeFig());
66:         addPathItem(textGroup, new PathConvPercent(this, 50, 10));
