268:             editor.damaged(_newItem);
269:             creationDrag(me.getX(), startPortFig.getY());
270:             editor.damaged(_newItem);
271:         }
272:         editor.scrollToShow(me.getX(), startPortFig.getY());
273:         me.consume();
274:     }
