25: package org.argouml.uml.diagram.sequence.ui;
26: 
27: import java.awt.Point;
28: import java.util.Collection;
29: import java.util.Iterator;
30: 
31: import org.argouml.model.Model;
32: import org.argouml.uml.diagram.sequence.LinkPort;
33: import org.argouml.uml.diagram.ui.FigEdgeModelElement;
34: import org.tigris.gef.base.Globals;
35: import org.tigris.gef.presentation.FigPoly;
36: 
37: /**
38:  * The fig for a link in a sequence diagram.
39:  *
40:  * @author jaap.branderhorst@xs4all.nl
41:  */
42: public abstract class FigMessage
43:     extends FigEdgeModelElement {
44: 
45:     private int computeRouteNumbersOfTime = 0;
46: 
47:     /**
48:      * Contructs a new figlink and sets the owner of the figlink.
49:      *
50:      * @param owner is the owner.
51:      */
52:     public FigMessage(Object owner) {
53:         super();
54:         setOwner(owner);
55:     }
56: 
57:     /**
58:      * Constructor here for saving and loading purposes.
59:      *
60:      */
61:     public FigMessage() {
62:         this(null);
63:     }
64: 
65:     /**
66:      * Returns the action attached to this link if any.<p>
67:      *
68:      * @return the action attached to this link or null if there isn't any.
69:      */
70:     public Object getAction() {
71:         Object owner = getOwner();
72:         if (owner != null && Model.getFacade().isALink(owner)) {
73:             Iterator it = Model.getFacade().getStimuli(owner).iterator();
74:             Object stimulus = it.next();
75:             if (stimulus != null) {
76:                 return Model.getFacade().getDispatchAction(stimulus);
77:             }
78:         }
79:         return null;
80:     }
81: 
82:     /**
83:      * Computes the route of this {@link FigMessage} and computes the
84:      * connectionpoints of the figlink to the ports.  This depends on
85:      * the action attached to the owner of the {@link FigMessage}.  Also
86:      * adds FigActivations etc or moves the {@link FigObject}s
87:      * if necessary.<p>
88:      *
89:      * @see org.tigris.gef.presentation.FigEdge#computeRoute()
90:      */
91:     public void computeRoute() {
92:         if (computeRouteNumbersOfTime == 0) {
93:             computeRouteNumbersOfTime++;
94:         } else if (computeRouteNumbersOfTime == 1) {
95:             Point srcPt = getSourcePortFig().center();
96:             Point dstPt = getSourcePortFig().center();
97:             Point centerPnt =
98:                 new Point(
99:                     (int) (srcPt.getX() > dstPt.getX()
100:                         ? (dstPt.getX() + (srcPt.getX() - dstPt.getX()))
101:                         : (srcPt.getX() + (dstPt.getX() - srcPt.getX()))),
102:                     (int) srcPt.getY());
103:             srcPt = getSourcePortFig().connectionPoint(centerPnt);
104:             dstPt = getDestPortFig().connectionPoint(centerPnt);
105:             setEndPoints(srcPt, dstPt);
106:             layoutEdge();
107:             computeRouteNumbersOfTime++;
108:             calcBounds();
109:         } else if (computeRouteNumbersOfTime > 1) {
110:             FigPoly p = ((FigPoly) _fig);
111: 
112:             Point srcPt = getSourcePortFig().center();
113:             Point dstPt = getDestPortFig().center();
114: 
115:             if (_useNearest) {
116:                 if (p.getNumPoints() == 2) {
117:                     //? two iterations of refinement, maybe should be a for-loop
118:                     srcPt = getSourcePortFig().connectionPoint(p.getPoint(1));
119:                     dstPt =
120:                         getDestPortFig().connectionPoint(
121:                             p.getPoint(p.getNumPoints() - 2));
122:                     srcPt = getSourcePortFig().connectionPoint(dstPt);
123:                     dstPt = getDestPortFig().connectionPoint(srcPt);
124:                 } else {
125:                     srcPt = getSourcePortFig().connectionPoint(p.getPoint(1));
126:                     dstPt =
127:                         getDestPortFig().connectionPoint(
128:                             p.getPoint(p.getNumPoints() - 2));
129:                 }
130:             }
131:             setEndPoints(srcPt, dstPt);
132:             calcBounds();
133:         }
134:     }
135: 
136:     /**
137:      * Returns the message belonging to this link if there is one
138:      * (otherwise null).<p>
139:      *
140:      * @return the message.
141:      */
142:     public Object getMessage() {
143:         Object action = getAction();
144:         if (action != null) {
145:             Collection col = Model.getFacade().getMessages(action);
146:             if (!col.isEmpty()) {
147:                 return col.iterator().next();
148:             }
149:         }
150:         return null;
151:     }
152: 
153:     /**
154:      * @see org.tigris.gef.presentation.FigEdgePoly#layoutEdge()
155:      */
156:     protected void layoutEdge() {
157:         layoutActivations();
158:         ((SequenceDiagramLayout) getLayer()).updateActivations();
159:         Globals.curEditor().damageAll();
160:     }
161: 
162:     /**
163:      * Lays out the activations to which the links is attached. Only
164:      * does this at creation time.
165:      */
166:     protected abstract void layoutActivations();
167: 
168:     /**
169:      * @return the destination link port
170:      */
171:     public LinkPort getDestLinkPort() {
172:         return (LinkPort) getDestPortFig().getOwner();
173:     }
174: 
175:     /**
176:      * @return the source linkport
177:      */
178:     public LinkPort getSrcLinkPort() {
179:         return (LinkPort) getSourcePortFig().getOwner();
180:     }
181: 
182:     /**
183:      * @return the source figobject
184:      */
185:     public FigObject getSrcFigObject() {
186:         return (FigObject) getSourceFigNode();
187:     }
188: 
189:     /**
190:      * @return the destination fig object
191:      */
192:     public FigObject getDestFigObject() {
193:         return (FigObject) getDestFigNode();
194:     }
195: 
196: }
