83:      * 3 times a distance of 2 between the rows + the stereoheight.
84:      */
85:     public static final int DEFAULT_HEIGHT =
86:         (3 * ROWHEIGHT + 3 * ROWDISTANCE + STEREOHEIGHT);
87: 
88:     /**
89:     * The defaultwidth of the object rectangle
90:     */
91:     public static final int DEFAULT_WIDTH = 3 * DEFAULT_HEIGHT / 2;
92: 
93:     /**
94:      * The outer black rectangle of the object box (object fig without
95:      * lifeline).
96:      */
97:     private FigRect outerBox;
98: 
99:     /**
100:      * The filled box for the object box (object fig without lifeline).
101:      */
102:     private FigRect backgroundBox;
103: 
104:     /**
105:      * The lifeline (dashed line under the object box to which activations are
106:      * attached)
107:      */
108:     private FigLine lifeLine;
109: 
110:     /**
111:      * The owner of the lifeline.
112:      */
113:     private LifeLinePort lifeLinePort;
114: 
115:     /**
116:      * The list where the nodes to which links can be attached are stored
117:      */
118:     private List linkPositions = new ArrayList();
119: 
120:     /**
121:      * The list where the figrects are stored that are the activation
122:      * boxes. The list is only here for performance issues. When
123:      * removing a figrect, it should also be removed from this list,
124:      * not only from the figs list.
125:      */
126:     private List figActivations = new ArrayList();
127: 
128:     /**
129:      * The list with the figLinkPorts. The list is only here for
130:      * performance issues. When deleting a figLinkPort, it should also
131:      * be removed from this list, not only from the figs list.
132:      */
133:     private List figFigLinkPorts = new ArrayList();
134: 
135:     /**
136:      * The comma seperated list of base names of the classifierRole(s)
137:      * that this object represents.
138:      */
139:     private String baseNames = "";
140: 
