235:     /**
236:      * Constructs the contents of the name text box and upates the name text box
237:      * accordingly. The contents of the name text box itself are NOT updated.
238:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#updateNameText()
239:      */
240:     protected void updateNameText() {
241:         String nameText =
242:             (objectName + "/" + classifierRoleNames + ":" + baseNames)
243:                 .trim();
