265:     /**
266:      * Sets the bounds and coordinates of this Fig. The outerbox (the
267:      * black box around the upper box) and the background box (the
268:      * white box at the background) are scaled to the given size. The
269:      * name text box and the stereo text box are moved to a correct
270:      * position.
271:      *
272:      * @see Fig#setBounds(int, int, int, int)
273:      */
274:     public void setBounds(int x, int y, int w, int h) {
275:         Rectangle oldBounds = getBounds();
276:         if (getNameFig().getWidth() > w) {
277:             w = getNameFig().getWidth() + 2 * MARGIN;
278:         }
279:         if (getStereotypeFig().getWidth() > w) {
280:             w = getStereotypeFig().getWidth() + 2 * MARGIN;
281:         }
282:         getNameFig().setCenter(
283:             new Point(x + w / 2,
284: 		      getNameFig().getY() - oldBounds.y + y
285: 		      + getNameFig().getHalfHeight()));
286:         getStereotypeFig().setCenter(
287:             new Point(
288:                 x + w / 2,
289:                 (getStereotypeFig().getY() - oldBounds.y
290: 		 + y + getStereotypeFig().getHalfHeight())));
291:         reSize(outerBox, x, y, w, h);
292:         reSize(backgroundBox, x, y, w, h);
293:         lifeLine.setBounds(
294:             outerBox.getX() + outerBox.getHalfWidth(),
295:             outerBox.getY() + outerBox.getHeight(),
296:             0,
297:             h - outerBox.getHeight());
298:         int factor = h / oldBounds.height;
299:         for (int i = 0; i < figActivations.size(); i++) {
300:             FigRect fig = (FigRect) figActivations.get(i);
301:             fig.setBounds(
302:                 x - oldBounds.x + fig.getX(),
303:                 y - oldBounds.y + fig.getY(),
304:                 fig.getWidth(),
305:                 fig.getHeight());
306:         }
307:         for (int i = 0; i < figFigLinkPorts.size(); i++) {
308:             FigLinkPort fig = (FigLinkPort) figFigLinkPorts.get(i);
309:             fig.setBounds(
310:                 x - oldBounds.x + fig.getX(),
311:                 y - oldBounds.y + fig.getY(),
312:                 fig.getWidth(),
313:                 fig.getHeight());
314:         }
315:         calcBounds(); //_x = x; _height = y; _w = w; _h = h;
316:         firePropChange("bounds", oldBounds, getBounds());
317:     }
