739:     private int getYCoordinateForActivationBox(Node node, boolean start) {
740:         int y = getYCoordinate(node);
741:         if (node instanceof ActivationNode) {
742:             if (node instanceof ObjectNode) {
743:                 y = y + outerBox.getHalfHeight();
744:             } else {
745:                 ActivationNode activationNode = (ActivationNode) node;
746:                 if (start
747:                     && activationNode.isStart()
748:                     && !activationNode.isCutOffTop()) {
749:                     y -= SequenceDiagramLayout.LINK_DISTANCE / 2;
750:                 } else if (
751:                     !start
752:                         && activationNode.isEnd()
753:                         && !activationNode.isCutOffBottom()) {
754:                     y += SequenceDiagramLayout.LINK_DISTANCE / 2;
755:                 }
756:             }
757:         }
758:         return y;
759:     }
