116:         // System to provide proper translation/i18n.
117:         org.argouml.cognitive.Translator.setTranslator(
118:                 new AbstractCognitiveTranslator() {
119:             public String i18nlocalize(String key) {
120:                 return Translator.localize(key);
121:             }
122: 
