698:     public void run() {
699: 
700:         Class c = null;
701:         if (c == null) // otherwise anoying warning
702:             LOG.info("preloading...");
703: 
704: 	// Alphabetic order
705:         c = org.argouml.kernel.DelayedChangeNotify.class;
