46: /**
47:  * Controls the look and feel and theme of ArgoUML. LookAndFeelMgr has a
48:  * "Look and Feel" property which represents the Swing Pluggable Look-and-feel.
49:  * It also has a "Theme" property which represents a MetalTheme when the
50:  * Metal look-and-feel is selected.
51:  *
52:  * @author Bob Tarling
53:  * @author Jeremy Jones
54:  */
55: public class LookAndFeelMgr {
56:     private static final Logger LOG = Logger.getLogger(LookAndFeelMgr.class);
57: 
58:     private static final LookAndFeelMgr	SINGLETON = new LookAndFeelMgr();
59: 
60:     // The Metal look and feel class name
61:     private static final String METAL_LAF_CLASS_NAME =
62: 	"javax.swing.plaf.metal.MetalLookAndFeel";
63: 
64:     // Display name and configuration key for default look and feel and theme
65:     private static final String			DEFAULT_KEY = "Default";
66: 
67:     // JasonsThemes
68:     private static final MetalTheme		DEFAULT_THEME =
69: 	new JasonsTheme();
70:     private static final MetalTheme		BIG_THEME =
71: 	new JasonsBigTheme();
72:     private static final MetalTheme		HUGE_THEME =
73: 	new JasonsHugeTheme();
74: 
75:     // The list of supported MetalThemes
76:     private static final MetalTheme[] THEMES = {
77:         DEFAULT_THEME,
78:         BIG_THEME,
79:         HUGE_THEME,
80:         new DefaultMetalTheme(),
81:     };
82: 
83:     /**
84:      * The class name of Swing's default look and feel (will be used if
85:      * the LookAndFeel property is null).
86:      **/
87:     private String				defaultLafClass;
88: 
89:     /**
90:      * get the single instance of the LookAndFeelMgr
91:      * @return the single instance of the LookAndFeelMgr
92:      */
93:     public static LookAndFeelMgr getInstance() {
94:         return SINGLETON;
95:     }
96: 
97:     /** Creates a new instance of LookAndFeelMgr. */
98:     private LookAndFeelMgr() {
99:         LookAndFeel laf = UIManager.getLookAndFeel();
100:         if (laf != null) {
101:             defaultLafClass = laf.getClass().getName();
102:         }
103:         else {
104:             defaultLafClass = null;
105:         }
106:     }
107: 
108:     /**
109:      * Sets the appearance of the UI using the current values of
110:      * the LookAndFeel and Theme properties.
111:      **/
112:     public void initializeLookAndFeel() {
113:         setLookAndFeel(getCurrentLookAndFeel());
114:         setTheme(getMetalTheme(getCurrentTheme()));
115:     }
116: 
117:     /**
118:      * Detecting the theme from the command line.
119:      *
120:      * @param arg the argument from the command line
121:      * @return the theme
122:      */
123:     public String getThemeClassNameFromArg(String arg) {
124:         if (arg.equalsIgnoreCase("-big")) {
125:             return BIG_THEME.getClass().getName();
126:         }
127:         else if (arg.equalsIgnoreCase("-huge")) {
128:             return HUGE_THEME.getClass().getName();
129:         }
130:         return null;
131:     }
132: 
133:     /**
134:      * Outputs command-line arguments supported by this class.
135:      **/
136:     public void printThemeArgs() {
137:         System.err.println("  -big            use big fonts");
138:         System.err.println("  -huge           use huge fonts");
139:     }
140: 
141:     /**
142:      * Returns the display names of the available look and feel choices.
143:      *
144:      * @return	look and feel display names
145:      **/
146:     public String[] getAvailableLookAndFeelNames() {
147:         UIManager.LookAndFeelInfo[] lafs = UIManager.getInstalledLookAndFeels();
148: 
149:         String[] names = new String[lafs.length + 1];
150:         names[0] = DEFAULT_KEY;
151:         for (int i = 0; i < lafs.length; ++i) {
152:             names[i + 1] = lafs[i].getName();
153:         }
154: 
155:         return names;
156:     }
157: 
158:     /**
159:      * Returns the display names of the available theme choices.
160:      *
161:      * @return	theme display names
162:      **/
163:     public String[] getAvailableThemeNames() {
164:         String[] names = new String[LookAndFeelMgr.THEMES.length];
165:         for (int i = 0; i < THEMES.length; ++i) {
166:             names[i] = THEMES[i].getName();
167:         }
168: 
169:         return names;
170:     }
171: 
172:     /**
173:      * Returns the Look and Feel class name identifier for the specified
174:      * display name, or null if no such Look and Feel is found.
175:      *
176:      * @param	name	display name of desired look and feel
177:      * @return			class name for desired look and feel
178:      **/
179:     public String getLookAndFeelFromName(String name) {
180:         if (name == null || DEFAULT_KEY.equals(name)) {
181:             return null;
182:         }
183: 
184:         String className = null;
185: 
186:         UIManager.LookAndFeelInfo[] lafs = UIManager.getInstalledLookAndFeels();
187:         for (int i = 0; i < lafs.length; ++i) {
188:             if (lafs[i].getName().equals(name)) {
189:                 className = lafs[i].getClassName();
190:             }
191:         }
192: 
193:         return className;
194:     }
195: 
196:     /**
197:      * Returns the theme class name identifier for the specified
198:      * display name, or null if no such theme is found.
199:      *
200:      * @param	name	display name of desired theme
201:      * @return			class name for desired theme
202:      **/
203:     public String getThemeFromName(String name) {
204:         if (name == null) {
205:             return null;
206:         }
207: 
208:         String className = null;
209: 
210:         for (int i = 0; i < THEMES.length; ++i) {
211:             if (THEMES[i].getName().equals(name)) {
212:                 className = THEMES[i].getClass().getName();
213:             }
214:         }
215: 
216:         return className;
217:     }
218: 
219:     /**
220:      * Returns true if the specified look and feel class
221:      * supports setting different themes.
222:      *
223:      * @param	lafClass	look and feel class name
224:      * @return				true if supports themes
225:      **/
226:     public boolean isThemeCompatibleLookAndFeel(String lafClass) {
227:         return (lafClass == null || lafClass.equals(METAL_LAF_CLASS_NAME));
228:     }
229: 
230:     /**
231:      * Returns the string identifier for the current look and feel.
232:      * This is the class name of the LookAndFeel class for the look and feel.
233:      * Returns null if no look and feel has been specified, in which case
234:      * Swing's default look and feel should be used.
235:      *
236:      * @return	current look and feel class name
237:      **/
238:     public String getCurrentLookAndFeel() {
239:         String value =
240: 	    Configuration.getString(Argo.KEY_LOOK_AND_FEEL_CLASS, null);
241:         if (DEFAULT_KEY.equals(value)) {
242:             value = null;
243:         }
244:         return value;
245:     }
246: 
247:     /**
248:      * Returns the display name of the current look and feel.
249:      *
250:      * @return	look and feel display name
251:      **/
252:     public String getCurrentLookAndFeelName() {
253:         String currentLookAndFeel = getCurrentLookAndFeel();
254: 
255:         if (currentLookAndFeel == null) {
256:             return DEFAULT_KEY;
257:         } 
258:         String name = null;
259:         
260:         UIManager.LookAndFeelInfo[] lafs =
261:             UIManager.getInstalledLookAndFeels();
262:         for (int i = 0; i < lafs.length; ++i) {
263:             if (lafs[i].getClassName().equals(currentLookAndFeel)) {
264:                 name = lafs[i].getName();
265:             }
266:         }
267:         
268:         return name;
269:     }
270: 
271:     /**
272:      * Sets the current look and feel, storing the new value in
273:      * Configuration.  If argument is null, indicates that Swing's default
274:      * look and feel should be used.
275:      *
276:      * @param	lafClass	class name of desired look and feel
277:      **/
278:     public void setCurrentLookAndFeel(String lafClass) {
279:         String currentLookAndFeel = getCurrentLookAndFeel();
280: 
281:         if ((lafClass == null && currentLookAndFeel == null)
282:             || (lafClass != null && lafClass.equals(currentLookAndFeel))) {
283:             return;
284:         }
285: 
286:         //setLookAndFeel(lafClass); Disabled until UI supports dynamic switching
287: 
288:         String lafValue = lafClass;
289:         if (lafValue == null) {
290:             lafValue = DEFAULT_KEY;
291:         }
292:         Configuration.setString(Argo.KEY_LOOK_AND_FEEL_CLASS, lafValue);
293:     }
294: 
295:     /**
296:      * Returns the string identifier for the current theme.
297:      * This is the class name of the MetalTheme class for the theme.
298:      * This method should never return null.
299:      *
300:      * @return	current theme class name
301:      **/
302:     public String getCurrentTheme() {
303: 	String value = Configuration.getString(Argo.KEY_THEME_CLASS, null);
304: 	if (DEFAULT_KEY.equals(value)) {
305: 	    value = null;
306: 	}
307: 	return value;
308:     }
309: 
310:     /**
311:      * Returns the display name of the current theme.
312:      *
313:      * @return	theme display name
314:      **/
315:     public String getCurrentThemeName() {
316:         String currentTheme = getCurrentTheme();
317: 
318:         if (currentTheme == null) {
319:             return DEFAULT_THEME.getName();
320:         } 
321:         String name = null;
322:         
323:         for (int i = 0; i < THEMES.length; ++i) {
324:             if (THEMES[i].getClass().getName().equals(currentTheme)) {
325:                 name = THEMES[i].getName();
326:             }
327:         }
328:         return name;
329:     }
330: 
331:     /**
332:      * Sets the current theme, storing the new value in
333:      * Configuration. Argument should not be null, and argument class
334:      * should be an instance of MetalTheme.
335:      *
336:      * @param	themeClass	class name of desired theme
337:      **/
338:     public void setCurrentTheme(String themeClass) {
339:         MetalTheme theme = getMetalTheme(themeClass);
340: 
341:         if (theme.getClass().getName().equals(getCurrentTheme())) {
342:             return;
343:         }
344: 
345:         //setTheme(theme); Disabled until UI supports dynamic switching
346: 
347:         String themeValue = themeClass;
348:         if (themeValue == null) {
349:             themeValue = DEFAULT_KEY;
350:         }
351:         Configuration.setString(Argo.KEY_THEME_CLASS, themeValue);
352:     }
353: 
354:     /**
355:      * @return the standard textfield font
356:      */
357:     public Font getStandardFont() {
358:         Font font = UIManager.getDefaults().getFont("TextField.font");
359:         if (font == null) {
360:             font = (new javax.swing.JTextField()).getFont();
361:         }
362:         return font;
363:     }
364: 
365:     /**
366:      * @return the small font
367:      */
368:     public Font getSmallFont() {
369:         Font font = getStandardFont();
370:         if (font.getSize2D() >= 12f) {
371:             return font.deriveFont(font.getSize2D() - 2f);
372:         }
373:         return font;
374:     }
375: 
376:     /**
377:      * Sets the look and feel in the GUI by calling UIManager.setLookAndFeel().
378:      *
379:      * @param	lafClass	class name of look and feel
380:      **/
381:     private void setLookAndFeel(String lafClass) {
382:         try {
383:             if (lafClass == null && defaultLafClass != null) {
384:                 // Set to the default LAF
385:                 UIManager.setLookAndFeel(defaultLafClass);
386:             } else {
387:                 // Set a custom LAF
388:                 UIManager.setLookAndFeel(lafClass);
389:             }
390:         } catch (UnsupportedLookAndFeelException e) {
391:             LOG.error(e);
392:         } catch (ClassNotFoundException e) {
393:             LOG.error(e);
394:         } catch (InstantiationException e) {
395:             LOG.error(e);
396:         } catch (IllegalAccessException e) {
397:             LOG.error(e);
398:         }
399:     }
400: 
401:     /**
402:      * Sets the metal theme in the GUI by calling
403:      * MetalLookAndFeel.setCurrentTheme().
404:      *
405:      * @param	theme	new MetalTheme to set
406:      **/
407:     private void setTheme(MetalTheme theme) {
408:         String currentLookAndFeel = getCurrentLookAndFeel();
409: 
410:         // If LAF is Metal (either set explicitly, or as the default)
411:         if ((currentLookAndFeel != null && currentLookAndFeel.equals(METAL_LAF_CLASS_NAME))
412: 	    || (currentLookAndFeel == null
413: 	        && defaultLafClass.equals(METAL_LAF_CLASS_NAME))) {
414:             try {
415:                 MetalLookAndFeel.setCurrentTheme(theme);
416:                 UIManager.setLookAndFeel(METAL_LAF_CLASS_NAME);
417:             } catch (UnsupportedLookAndFeelException e) {
418:                 LOG.error(e);
419:             } catch (ClassNotFoundException e) {
420:                 LOG.error(e);
421:             } catch (InstantiationException e) {
422:                 LOG.error(e);
423:             } catch (IllegalAccessException e) {
424:                 LOG.error(e);
425:             }
426:         }
427:     }
428: 
429:     /**
430:      * Returns the MetalTheme for the specified class name.
431:      * Returns the default theme if a corresponding MetalTheme class
432:      * can not be found.
433:      *
434:      * @param	themeClass	MetalTheme class name
435:      * @return				MetalTheme object for class name
436:      **/
437:     private MetalTheme getMetalTheme(String themeClass) {
438:         MetalTheme theme = null;
439: 
440:         for (int i = 0; i < THEMES.length; ++i) {
441:             if (THEMES[i].getClass().getName().equals(themeClass)) {
442:                 theme = THEMES[i];
443:             }
444:         }
445: 
446:         if (theme == null) {
447:             theme = DEFAULT_THEME;
448:         }
449: 
450:         return theme;
451:     }
452: }
