219:     /**
220:      * Returns true if the specified look and feel class
221:      * supports setting different themes.
222:      *
223:      * @param	lafClass	look and feel class name
224:      * @return				true if supports themes
225:      **/
226:     public boolean isThemeCompatibleLookAndFeel(String lafClass) {
227:         return (lafClass == null || lafClass.equals(METAL_LAF_CLASS_NAME));
228:     }
229: 
230:     /**
231:      * Returns the string identifier for the current look and feel.
232:      * This is the class name of the LookAndFeel class for the look and feel.
233:      * Returns null if no look and feel has been specified, in which case
234:      * Swing's default look and feel should be used.
235:      *
236:      * @return	current look and feel class name
237:      **/
238:     public String getCurrentLookAndFeel() {
239:         String value =
240: 	    Configuration.getString(Argo.KEY_LOOK_AND_FEEL_CLASS, null);
241:         if (DEFAULT_KEY.equals(value)) {
242:             value = null;
243:         }
244:         return value;
245:     }
246: 
247:     /**
248:      * Returns the display name of the current look and feel.
249:      *
250:      * @return	look and feel display name
251:      **/
252:     public String getCurrentLookAndFeelName() {
253:         String currentLookAndFeel = getCurrentLookAndFeel();
254: 
255:         if (currentLookAndFeel == null) {
256:             return DEFAULT_KEY;
257:         } 
258:         String name = null;
259:         
260:         UIManager.LookAndFeelInfo[] lafs =
261:             UIManager.getInstalledLookAndFeels();
262:         for (int i = 0; i < lafs.length; ++i) {
263:             if (lafs[i].getClassName().equals(currentLookAndFeel)) {
264:                 name = lafs[i].getName();
265:             }
266:         }
267:         
268:         return name;
269:     }
270: 
271:     /**
272:      * Sets the current look and feel, storing the new value in
273:      * Configuration.  If argument is null, indicates that Swing's default
274:      * look and feel should be used.
275:      *
276:      * @param	lafClass	class name of desired look and feel
277:      **/
278:     public void setCurrentLookAndFeel(String lafClass) {
279:         String currentLookAndFeel = getCurrentLookAndFeel();
280: 
281:         if ((lafClass == null && currentLookAndFeel == null)
282:             || (lafClass != null && lafClass.equals(currentLookAndFeel))) {
283:             return;
284:         }
285: 
286:         //setLookAndFeel(lafClass); Disabled until UI supports dynamic switching
287: 
288:         String lafValue = lafClass;
289:         if (lafValue == null) {
290:             lafValue = DEFAULT_KEY;
291:         }
292:         Configuration.setString(Argo.KEY_LOOK_AND_FEEL_CLASS, lafValue);
293:     }
