73: /**
74:  * The TabDiagram is the tab in the multieditorpane that holds a diagram. The 
75:  * TabDiagram consists of a JGraph (with the figs) and a toolbar. It is possible
76:  * to spawn objects of this class into a dialog via the spawn method of its
77:  * parent.
78:  */
79: public class TabDiagram
80:     extends TabSpawnable
81:     implements TabModelTarget, GraphSelectionListener, ModeChangeListener {
82: 
83:     private static final Logger LOG = Logger.getLogger(TabDiagram.class);
84: 
85:     ////////////////////////////////////////////////////////////////
86:     // instance variables
87: 
88:     /**
89:      * The diagram object.
90:      */
91:     protected UMLDiagram _target;
92: 
93:     /**
94:      * The GEF JGraph in where the figs are painted
95:      */
96:     protected JGraph _jgraph;
97:     
98:     /**
99:      * prevents target event cycles between this and the TargetManager.
100:      */
101:     private boolean updatingSelection = false;
102: 
103:     /**
104:      * used but there doesn't appear to be a purpose.
105:      */
106:     protected boolean _shouldBeEnabled = true;
107: 
108:     /**
109:      * The toolbar that is positioned just above
110:      * the diagram containing the drawing tools.
111:      */
112:     protected JToolBar _toolBar;
113: 
114:     ////////////////////////////////////////////////////////////////
115:     // constructors
116: 
117:     /**
118:      * calls the other constructor.
119:      */
120:     public TabDiagram() {
121:         this("Diagram");
122:     }
123: 
124:     public TabDiagram(String tag) {
125:         super(tag);
126:         setLayout(new BorderLayout());
127:         _jgraph = new ArgoJGraph();
128:         _jgraph.setDrawingSize((612 - 30) * 2, (792 - 55 - 20) * 2);
129:         // TODO: should update to size of diagram contents
130: 
131:         Globals.setStatusBar(ProjectBrowser.getInstance());
132:         JPanel p = new JPanel();
133:         p.setLayout(new BorderLayout());
134:         p.setBorder(new EtchedBorder(EtchedBorder.LOWERED));
135:         p.add(_jgraph, BorderLayout.CENTER);
136:         add(p, BorderLayout.CENTER);
137:         _jgraph.addGraphSelectionListener(this);
138:         _jgraph.addModeChangeListener(this);
139:     }
140: 
141:     /**
142:      * The clone method that should clone the JGraph with it's contents and
143:      * the toolbar with it's contents. Since both JGraph as the toolbar are
144:      * coming from the GEF framework, cloning them will be hard work and should
145:      * actually not be placed here but in a clone method of the JGraph and the
146:      * Toolbar.
147:      * @see java.lang.Object#clone()
148:      */
149:     public Object clone() {
150:         // next statement gives us a clone JGraph but not a cloned Toolbar
151:         TabDiagram newPanel = new TabDiagram();
152:         if (_target != null) {
153:             newPanel.setTarget(_target);
154:         }
155:         newPanel.setToolBar(ToolBarFactory.createToolBar(true/*rollover*/,
156:                                                          _target.getActions(),
157:                                                          false/*floating*/));
158:         setToolBar(ToolBarFactory.createToolBar(true/*rollover*/,
159:                                                 _target.getActions(),
160:                                                 false/*floating*/));
161:         return newPanel;
162:     }
163: 
164:     /**
165:      * Sets the target of the tab. The target should allways be an instance of
166:      * UMLDiagram
167:      * @param t
168:      * @deprecated As of ArgoUml version 0.13.5, the visibility of
169:      * this method will change in the future, replaced by {@link
170:      * org.argouml.ui.targetmanager.TargetManager}.
171:      */
172:     public void setTarget(Object t) {
173: 
174:         if (!(t instanceof UMLDiagram)) {
175:             _shouldBeEnabled = false;
176:             // This is perfectly normal and happens among other things
177:             // within the call to setDiagram (below).
178:             LOG.debug("target is null in set target or "
179: 		      + "not an instance of UMLDiagram");
180:             return;
181:         }
182:         if (_target != null) {
183:             _target.removeAsTarget();
184:         }
185:         UMLDiagram target = (UMLDiagram) t;
186: 
187:         target.setAsTarget();
188: 
189:         _shouldBeEnabled = true;
190:         setToolBar(target.getJToolBar());
191:         _jgraph.removeGraphSelectionListener(this);
192:         _jgraph.setDiagram(target);
193:         _jgraph.addGraphSelectionListener(this);
194:         _target = target;
195:     }
