408:      * performance. 
409:      *
410:      */
411:     public void removeAsTarget() {
412:         Enumeration elems = elements();
413:         UmlModelEventPump pump = UmlModelEventPump.getPump();
414:         while (elems.hasMoreElements()) {
415:             Object o = elems.nextElement();
416:             if (ModelFacade.isAElementListener(o)) {
417:                 MElementListener listener = (MElementListener) o;
418:                 Fig fig = (Fig) o;
419:                 pump.removeModelEventListener(listener, fig.getOwner());
420:             }
