295:         posn += manipulateActions.length;
296:         System.arraycopy(umlActions, 0, actions, posn, umlActions.length);
297:         posn += umlActions.length;
298:         System.arraycopy(shapeActions, 0, actions, posn, shapeActions.length);
299: 
300:         return actions;
301:     }
