64: /**
65:  * To persist to and from argo (xml file) storage.
66:  *
67:  * @author Bob Tarling
68:  */
69: public class UmlFilePersister extends AbstractFilePersister {
70:     /**
71:      * Logger.
72:      */
73:     private static final Logger LOG =
74:         Logger.getLogger(UmlFilePersister.class);
75: 
76:     private static final String ARGO_TEE = "/org/argouml/persistence/argo2.tee";
77: 
78:     /**
79:      * The constructor.
80:      */
81:     public UmlFilePersister() {
82:     }
83: 
84:     /**
85:      * @see org.argouml.persistence.AbstractFilePersister#getExtension()
86:      */
87:     public String getExtension() {
88:         return "uml";
89:     }
90: 
91:     /**
92:      * @see org.argouml.persistence.AbstractFilePersister#getDesc()
93:      */
94:     protected String getDesc() {
95:         return "ArgoUML project file";
96:     }
97: 
98:     /**
99:      * It is being considered to save out individual
100:      * xmi's from individuals diagrams to make
101:      * it easier to modularize the output of Argo.
102:      *
103:      * @param file The file to write.
104:      * @param project the project to save
105:      * @throws SaveException when anything goes wrong
106:      *
107:      * @see org.argouml.persistence.ProjectFilePersister#save(
108:      * org.argouml.kernel.Project, java.io.File)
109:      */
110:     public void doSave(Project project, File file)
111:         throws SaveException {
112: 
113:         File lastArchiveFile = new File(file.getAbsolutePath() + "~");
114:         File tempFile = null;
115:         
116:         try {
117:             tempFile = createTempFile(file);
118:         } catch (FileNotFoundException e) {
119:             throw new SaveException(
120:                     "Failed to archive the previous file version", e);
121:         } catch (IOException e) {
122:             throw new SaveException(
123:                     "Failed to archive the previous file version", e);
124:         }
125:         
126:         try {
127: 
128:             project.setFile(file);
129:             project.setVersion(ArgoVersion.getVersion());
130:             project.setPersistenceVersion(PERSISTENCE_VERSION);
131: 
132:             FileOutputStream stream =
133:                 new FileOutputStream(file);
134: 
135:             writeProject(project, stream);
136: 
137:             stream.close();
138: 
139:             String path = file.getParent();
140:             if (LOG.isInfoEnabled()) {
141:                 LOG.info("Dir ==" + path);
142:             }
143: 
144:             // if save did not raise an exception
145:             // and name+"#" exists move name+"#" to name+"~"
146:             // this is the correct backup file
147:             if (lastArchiveFile.exists()) {
148:                 lastArchiveFile.delete();
149:             }
150:             if (tempFile.exists() && !lastArchiveFile.exists()) {
151:                 tempFile.renameTo(lastArchiveFile);
152:             }
153:             if (tempFile.exists()) {
154:                 tempFile.delete();
155:             }
156:         } catch (Exception e) {
157:             LOG.error("Exception occured during save attempt", e);
158: 
159:             // frank: in case of exception
160:             // delete name and mv name+"#" back to name if name+"#" exists
161:             // this is the "rollback" to old file
162:             file.delete();
163:             tempFile.renameTo(file);
164:             // we have to give a message to user and set the system to unsaved!
165:             throw new SaveException(e);
166:         }
167:     }
168: 
169:     /**
170:      * Write the output for a project on the given stream.
171:      *
172:      * @param project The project to output.
173:      * @param stream The stream to write to.
174:      * @throws SaveException If something goes wrong.
175:      */
176:     void writeProject(Project project, OutputStream stream)
177:         throws SaveException {
178:         OutputStreamWriter outputStreamWriter;
179:         try {
180:             outputStreamWriter = new OutputStreamWriter(stream, "UTF-8");
181:         } catch (UnsupportedEncodingException e) {
182:             throw new SaveException(e);
183:         }
184:         PrintWriter writer =
185:             new PrintWriter(new BufferedWriter(outputStreamWriter));
186: 
187:         try {
188:             Integer indent = new Integer(4);
189: 
190:             writer.println("<?xml version = \"1.0\" "
191:                     + "encoding = \"" + "UTF-8" + "\" ?>");
192:             writer.println("<uml version=\"" + PERSISTENCE_VERSION + "\">");
193:             // Write out header section
194:             try {
195:                 Hashtable templates =
196:                     TemplateReader.getInstance().read(ARGO_TEE);
197:                 OCLExpander expander = new OCLExpander(templates);
198:                 expander.expand(writer, project, "  ");
199:                 // For next version of GEF:
200:                 // expander.expand(writer, project, "  ");
201:             } catch (FileNotFoundException e) {
202:                 throw new SaveException(e);
203:             } catch (ExpansionException e) {
204:                 throw new SaveException(e);
205:             }
206: 
207:             // Write out XMI section first
208:             int size = project.getMembers().size();
209:             for (int i = 0; i < size; i++) {
210:                 ProjectMember projectMember =
211:                     (ProjectMember) project.getMembers().get(i);
212:                 if (projectMember.getType().equalsIgnoreCase("xmi")) {
213:                     if (LOG.isInfoEnabled()) {
214:                         LOG.info("Saving member of type: "
215:                               + ((ProjectMember) project.getMembers()
216:                                     .get(i)).getType());
217:                     }
218:                     MemberFilePersister persister = null;
219:                     if (projectMember instanceof ProjectMemberDiagram) {
220:                         persister = new DiagramMemberFilePersister();
221:                     } else if (projectMember instanceof ProjectMemberTodoList) {
222:                         persister = new TodoListMemberFilePersister();
223:                     } else if (projectMember instanceof ProjectMemberModel) {
224:                         persister = new ModelMemberFilePersister();
225:                     }
226:                     persister.save(projectMember, writer, indent);
227:                 }
228:             }
229: 
230:             // Write out all non-XMI sections
231:             for (int i = 0; i < size; i++) {
232:                 ProjectMember projectMember =
233:                     (ProjectMember) project.getMembers().get(i);
234:                 if (!projectMember.getType().equalsIgnoreCase("xmi")) {
235:                     if (LOG.isInfoEnabled()) {
236:                         LOG.info("Saving member of type: "
237:                               + ((ProjectMember) project.getMembers().
238:                                     get(i)).getType());
239:                     }
240:                     MemberFilePersister persister = null;
241:                     if (projectMember instanceof ProjectMemberDiagram) {
242:                         persister = new DiagramMemberFilePersister();
243:                     } else if (projectMember instanceof ProjectMemberTodoList) {
244:                         persister = new TodoListMemberFilePersister();
245:                     } else if (projectMember instanceof ProjectMemberModel) {
246:                         persister = new ModelMemberFilePersister();
247:                     }
248:                     persister.save(projectMember, writer, indent);
249:                 }
250:             }
251: 
252:             writer.println("</uml>");
253: 
254:             writer.flush();
255:         } finally {
256:             writer.close();
257:         }
258:     }
259: 
260:     /**
261:      * @see org.argouml.persistence.ProjectFilePersister#doLoad(java.net.URL,
262:      * javax.swing.JProgressBar, javax.swing.text.JTextComponent progressText)
263:      */
264:     public Project doLoad(URL file, JProgressBar progressBar, JTextComponent progressText) throws OpenException {
265:         try {
266:             Project p = new Project(file);
267: 
268:             // Run through any stylesheet upgrades
269:             file = upgrade(file);
270: 
271:             XmlInputStream inputStream =
272:                         new XmlInputStream(file.openStream(), "argo");
273: 
274:             ArgoParser parser = new ArgoParser();
275:             parser.readProject(p, inputStream);
276: 
277:             List memberList = parser.getMemberList();
278: 
279:             LOG.info(memberList.size() + " members");
280: 
281:             MemberFilePersister persister = null;
282:             for (int i = 0; i < memberList.size(); ++i) {
283:                 if (memberList.get(i).equals("pgml")) {
284:                     persister = new DiagramMemberFilePersister();
285:                 } else if (memberList.get(i).equals("todo")) {
286:                     persister = new TodoListMemberFilePersister();
287:                 } else if (memberList.get(i).equals("xmi")) {
288:                     persister = new ModelMemberFilePersister();
289:                 }
290:                 LOG.info("Loading member with "
291:                         + persister.getClass().getName());
292:                 inputStream.reopen(persister.getMainTag());
293:                 persister.load(p, inputStream);
294:             }
295:             inputStream.realClose();
296:             p.postLoad();
297:             return p;
298:         } catch (IOException e) {
299:             LOG.error("IOException", e);
300:             throw new OpenException(e);
301:         } catch (SAXException e) {
302:             LOG.error("SAXException", e);
303:             throw new OpenException(e);
304:         }
305:     }
306: 
307:     private URL upgrade(URL url) throws OpenException {
308:         try {
309:             int versionFromFile = Integer.parseInt(getVersion(url));
310: 
311:             LOG.info("Loading uml file of version " + versionFromFile);
312:             while (versionFromFile < PERSISTENCE_VERSION) {
