221:                     } else if (projectMember instanceof ProjectMemberTodoList) {
222:                         persister = new TodoListMemberFilePersister();
223:                     } else if (projectMember instanceof ProjectMemberModel) {
224:                         persister = new ModelMemberFilePersister();
225:                     }
