680:     public String generateTaggedValues(Object handle) {
681: 	MModelElement e = (MModelElement)handle;
682: 	Collection tvs = e.getTaggedValues();
683: 	if (tvs == null || tvs.size() == 0) return "";
684: 	boolean first = true;
685: 	StringBuffer buf = new StringBuffer();
686: 	Iterator iter = tvs.iterator();
687: 	String s = null;
688: 	while (iter.hasNext()) {
689: 	    s = generateTaggedValue((MTaggedValue) iter.next());
690: 	    if (s != null && s.length() > 0) {
691: 		if (first) {
692: 		    /*
693: 		     * Corrected 2001-09-26 STEFFEN ZSCHALER
694: 		     *
695: 		     * Was:
696: 		     buf.append("// {");
697: 		     *
698: 		     * which caused problems with new lines characters in tagged values
699: 		     * (e.g. comments...). The new version still has some problems with
700: 		     * tagged values containing "*"+"/" as this closes the comment
701: 		     * prematurely, but comments should be taken out of the tagged values
702: 		     * list anyway...
703: 		     */
