860: 	    public void caseAConstraintBody (tudresden.ocl.parser.node.AConstraintBody node) {
861: 		// We don't care for anything below this node, so we do not use apply anymore.
862: 		String sKind = (node.getStereotype() != null) ?
863: 		    (node.getStereotype().toString()) :
864: 		    (null);
865: 		String sExpression = (node.getExpression() != null) ?
866: 		    (node.getExpression().toString()) :
867: 		    (null);
868: 		String sName = (node.getName() != null) ?
869: 		    (node.getName().getText()) :
870: 		    (m_sConstraintName + "_" + (m_nConstraintID++));
871: 
872: 		if ((sKind == null) ||
873: 		    (sExpression == null)) {
874: 		    return;
875: 		}
876: 
877: 		String sTag;
878: 		if (sKind.equals ("inv ")) {
879: 		    sTag = "@invariant ";
880: 		}
881: 		else if (sKind.equals ("post ")) {
882: 		    sTag = "@post-condition ";
883: 		}
884: 		else if (sKind.equals ("pre ")) {
885: 		    sTag = "@pre-condition ";
886: 		}
887: 		else {
888: 		    return;
889: 		}
890: 
891: 		sTag += sName + ": " + sExpression;
892: 		m_llsTags.addLast (sTag);
893: 	    }
894: 	}
895: 
896: 	tudresden.ocl.check.types.ModelFacade mf = new org.argouml.ocl.ArgoFacade (me);
897: 	for (Iterator i = cConstraints.iterator(); i.hasNext();) {
