497: 	String classifierKeyword;
498: 	if (cls instanceof MClass) classifierKeyword = "class";
499: 	else if (cls instanceof MInterface) classifierKeyword = "interface";
500: 	else return ""; // actors and use cases
501: 
502: 	StringBuffer sb = new StringBuffer(80);
503: 	sb.append(DocumentationManager.getComments(cls));  // Add the comments for this classifier first.
504: 
505: 	/*
506: 	 * Replaced 2001-09-26 STEFFEN ZSCHALER
507: 	 *
508: 	 * Was:
509: 	 *
510: 	 sb.append(DocumentationManager.getDocs(cls)).append("\n");
511: 	*/
512: 	sb.append (generateConstraintEnrichedDocComment (cls)).append ("\n");
513: 
514: 	sb.append(generateVisibility(cls.getVisibility()));
515: 	if (cls.isAbstract() && !(cls instanceof MInterface)) {
516: 	    if (VERBOSE) sb.append("/* abstract */ ");
517: 	}
518: 	if (cls.isLeaf()) {
519: 	    if (VERBOSE) sb.append("/* final */ ");
520: 	}
521: 	sb.append(classifierKeyword).append(" ").append(generatedName);
522: 	String baseClass = generateGeneralzation(cls.getGeneralizations());
523: 	String tv = null;
524: 	if (!baseClass.equals("")) sb.append(' ').append(": ").append(baseClass);
525: 
526: 	// nsuml: realizations!
527: 	if (cls instanceof MClass) {
528: 	    String interfaces = generateSpecification((MClass) cls);
529: 	    if (!interfaces.equals("")) {
530: 		if (baseClass.equals(""))
531: 		    sb.append(": ");
532: 		else
533: 		    sb.append(", ");
534: 		sb.append(interfaces);
535: 	    }
536: 	}
537: 	sb.append("\n{");
538: 
539: 	tv = generateTaggedValues(cls);
540: 	if (tv != null && tv.length() > 0) sb.append(INDENT).append(tv);
541: 
542: 	// sb.append(generateConstraints(cls)); Removed 2001-09-26 STEFFEN ZSCHALER
543: 
544: 
545: 	// generate constructor (Marian Heddesheimer)
546: 	String make_constructor = cls.getTaggedValue("constructor");
547: 	if ( (make_constructor != null) && (make_constructor.equals("true")) ) {
548: 	    sb.append(INDENT).append("function ").append(cls.getName()).append("() {\n");
549: 	    sb.append(generateSection(cls));
550: 	    sb.append(INDENT).append("}\n");
551: 	}
552: 
553: 
554: 	Collection strs = UmlHelper.getHelper().getCore().getAttributes(cls);
555: 	if (strs != null) {
556: 	    sb.append('\n');
557: 
558: 	    if (cls instanceof MClass) sb.append(INDENT).append("// Attributes\n");
559: 	    Iterator strEnum = strs.iterator();
560: 	    while (strEnum.hasNext()) {
561: 		MStructuralFeature sf = (MStructuralFeature) strEnum.next();
562: 		sb.append('\n').append(INDENT).append(generate(sf));
563: 		tv = generateTaggedValues(sf);
564: 		if (tv != null && tv.length() > 0) sb.append(INDENT).append(tv).append('\n');
565: 	    }
566: 	}
567: 
568: 	Collection ends = cls.getAssociationEnds();
569: 	if (ends != null) {
570: 	    sb.append('\n');
571: 	    if (cls instanceof MClass) sb.append(INDENT).append("// Associations\n");
572: 	    Iterator endEnum = ends.iterator();
573: 	    while (endEnum.hasNext()) {
574: 		MAssociationEnd ae = (MAssociationEnd) endEnum.next();
575: 		MAssociation a = ae.getAssociation();
576: 		sb.append('\n').append(INDENT).append(generateAssociationFrom(a, ae));
577: 		tv = generateTaggedValues(a);
578: 		if (tv != null && tv.length() > 0) sb.append(INDENT).append(tv);
579: 
580: 		// sb.append(generateConstraints(a));  Removed 2001-09-26 STEFFEN ZSCHALER Why was this not in generateAssociationFrom ?
581: 	    }
582: 	}
583: 
584: 	// TODO: constructors
585: 	Collection behs = UmlHelper.getHelper().getCore().getOperations(cls);
586: 	if (behs != null) {
587: 	    sb.append ('\n');
588: 	    sb.append (INDENT).append ("// Operations\n");
589: 
590: 	    Iterator behEnum = behs.iterator();
591: 
592: 	    while (behEnum.hasNext()) {
593: 		MBehavioralFeature bf = (MBehavioralFeature) behEnum.next();
594: 
595: 		sb.append ('\n').append (INDENT).append (generate (bf));
596: 
597: 		tv = generateTaggedValues((MModelElement) bf);
598: 
599: 		if ((cls instanceof MClass) &&
600: 		    (bf instanceof MOperation) &&
601: 		    (!((MOperation) bf).isAbstract())) {
602: 		    sb.append ('\n').append (INDENT).append ("{\n");
603: 
604: 		    if (tv.length() > 0) sb.append (INDENT).append (tv);
605: 
606: 		    sb.append (generateMethodBody ((MOperation) bf)).append ('\n')
607: 			.append (INDENT).append ("}\n");
608: 		}
609: 		else {
610: 		    sb.append (";\n");
611: 		    if (tv.length() > 0) sb.append (INDENT).append (tv).append ('\n');
612: 		}
613: 	    }
614: 	}
615: 	sb.append("} /* end ").append(classifierKeyword).append(' ').append(generatedName).append(" */\n");
616: 
617: 	return sb.toString();
618:     }
