1189: 	if (lower == null && upper == null) return ANY_RANGE;
1190: 	if (lower == null) return "*.." + upper.toString();
1191: 	if (upper == null) return lower.toString() + "..*";
1192: 	if (lower.intValue() == upper.intValue()) return lower.toString();
1193: 	return lower.toString() + ".." + upper.toString();
1194: 
