81:     public String convertValueToText(
82:         Object value,
83:         boolean selected,
84:         boolean expanded,
85:         boolean leaf,
86:         int row,
87:         boolean hasFocus) {
88:         
89:         // do model elements first
90:         if (value instanceof MModelElement){
91:             
92:             String name=null;
93:             
94:             if (value instanceof MTransition || value instanceof MExtensionPoint) { // Jeremy Bennett patch
95:                 name = GeneratorDisplay.Generate(value);
96:             }
97:             else{
98:                 name = ((MModelElement)value).getName();
99:             }
100:             
101:             if (name == null || name.equals("")){
102:                 
103:                 name = "(anon " + ((MModelElement)value).getUMLClassName() + ")";
104:             }
105:             
106:             // Look for stereotype
107:             if (showStereotype) {
108:                 MStereotype st = ((MModelElement) value).getStereotype();
109:                     if (st != null) {
110:                         name += " " + GeneratorDisplay.Generate(st);
111:                 }
112:             }
113:             
114:             return name;
115:         }
116:         
117:         if (value instanceof ToDoItem) {
118:             return ((ToDoItem) value).getHeadline();
119:         }
120:         if (value instanceof ToDoList) {
121:             return "ToDoList";
