360:     public synchronized void onceMore() {
361:         if (!_queued) {
362:             _queued = true;
363:             SwingUtilities.invokeLater(this);
364:         }
365:         _timesToRun++;
366:     }
367: 
368:     public synchronized void run() {
369:         if (_timesToRun > 100)
370:             cat.debug("" + _timesToRun + " forceUpdates encountered.");
371: 
372:         if (_timesToRun > 0) {
373:             // another forceUpdate was seen, wait again
374:             _queued = true;
375:             SwingUtilities.invokeLater(this);
376:             _timesToRun = 0;
377:         } else if (_queued) {
378:             _queued = false;
379:             SwingUtilities.invokeLater(this);
380:         } else {
381:             _tree.doForceUpdate();
382:         }
383:     }
