32: /**
33:  * Same as the standard java class GridLayout but allows more
34:  * flexability for sizing of columns and rows.
35:  *
36:  * @author Bob Tarling
37:  */
38: public class GridLayout2 implements LayoutManager, java.io.Serializable {
39: 
40:      /**
41:        * Do not resize the child components.
42:        */
43:     public static final int NONE = 0;
44: 
45:      /**
46:        * Resize all child components to fit their cell both
47:        * horizontally and vertically.
48:        */
49:     public static final int BOTH = 1;
50: 
51:      /**
52:        * Resize all child components to fit their cell horizontally
53:        * but not vertically.
54:        */
55:     public static final int HORIZONTAL = 2;
56: 
57:      /**
58:        * Resize all child components to fit their cell vertically but
59:        * not horizontally.
60:        */
61:     public static final int VERTICAL = 3;
62: 
63:      /**
64:       * Put the component in the center of its display area.
65:       */
66:     public static final int CENTER = 10;
67: 
68:      /**
69:        * Put the component at the top of its display area,
70:        * centered horizontally.
71:        */
72:     public static final int NORTH = 11;
73: 
74:       /**
75:        * Put the component at the top-right corner of its display area.
76:        */
77:     public static final int NORTHEAST = 12;
78: 
79:       /**
80:        * Put the component on the right side of its display area,
81:        * centered vertically.
82:        */
83:     public static final int EAST = 13;
84: 
85:       /**
86:        * Put the component at the bottom-right corner of its display area.
87:        */
88:     public static final int SOUTHEAST = 14;
89: 
90:       /**
91:        * Put the component at the bottom of its display area, centered
92:        * horizontally.
93:        */
94:     public static final int SOUTH = 15;
95: 
96:      /**
97:        * Put the component at the bottom-left corner of its display area.
98:        */
99:     public static final int SOUTHWEST = 16;
100: 
101:       /**
102:        * Put the component on the left side of its display area,
103:        * centered vertically.
104:        */
105:     public static final int WEST = 17;
106: 
107:      /**
108:        * Put each component in the top-left corner of its display area.
109:        */
110:     public static final int NORTHWEST = 18;
111: 
112:     /**
113:      * This is the horizontal gap (in pixels) which specifies the space
114:      * between columns.  They can be changed at any time.
115:      * This should be a non negative integer.
116:      *
117:      * @serial
118:      * @see #getHgap()
119:      * @see #setHgap(int)
120:      */
121:     private int h;
122:     /**
123:      * This is the vertical gap (in pixels) which specifies the space
124:      * between rows.  They can be changed at any time.
125:      * This should be a non negative integer.
126:      *
127:      * @serial
128:      * @see #getVgap()
129:      * @see #setVgap(int)
130:      */
131:     private int vgap;
132:     /**
133:      * This is the number of rows specified for the grid.  The number
134:      * of rows can be changed at any time.
135:      * This should be a non negative integer, where '0' means
136:      * 'any number' meaning that the number of Rows in that
137:      * dimension depends on the other dimension.
138:      *
139:      * @serial
140:      * @see #getRows()
141:      * @see #setRows(int)
142:      */
143:     private int rows;
144:     /**
145:      * This is the number of columns specified for the grid.  The number
146:      * of columns can be changed at any time.
147:      * This should be a non negative integer, where '0' means
148:      * 'any number' meaning that the number of Columns in that
149:      * dimension depends on the other dimension.
150:      *
151:      * @serial
152:      * @see #getColumns()
153:      * @see #setCols(int)
154:      */
155:     private int cols;
156: 
157:     /**
158:      * Size all cells as the largest prefered width and height
159:      * component. <p>
160:      *
161:      * A possible value for the cellSizing parameter of the
162:      * constructor in order to size cells so that each have the same
163:      * width and height. The width is the largest prefered width and
164:      * the height is the largest prefered height of all these child
165:      * components.
166:      */
167:     public static final int MAXPREFERRED = 20;
168: 
169:     /**
170:      * Size all cells so that all in the same row are the same height
171:      * and all in the same column are the same width.<p>
172:      *
173:      * A possible value for the cellSizing parameter of the
174:      * constructor. The width is the largest prefered width of all
175:      * components in the same column and the height is the largest
176:      * prefered height of all components in the same row.
177:      */
178:     public static final int ROWCOLPREFERRED = 21;
179: 
180:     /**
181:      * Size all cells as the same width and height to fit the parent
182:      * component. <p>
183:      *
184:      * A possible value for the cellSizing parameter of the
185:      * constructor in order to size cells so that each has the same
186:      * height and width and are sized to fit their parent.  This
187:      * emulates the sizing done by a standard GridLayout.
188:      */
189:     public static final int FITPARENT = 22;
190: 
191:     int cellSizing = FITPARENT;
192: 
193:     private int fill = BOTH;
194:     private int anchor = WEST;
195: 
196:     /**
197:      * The height of the child component with the largest height
198:      */
199:     protected int largestHeight;
200:     /**
201:      * The width of the child component with the largest width
202:      */
203:     protected int largestWidth;
204:     /**
205:      * The required cell width of each column
206:      */
207:     protected int[] colWidth;
208:     /**
209:      * The required cell height of each row
210:      */
211:     protected int[] rowHeight;
