232:     /**
233:      * Construct a new GridLayout2 with the specified number of rows
234:      * and columns and cell spacing.
235:      *
236:      * @param r the number of rows in the layout
237:      * @param c the number of columns in the layout
238:      * @param hgap the horizontal gap between cells
239:      * @param vgap the vertical gap between cells
240:      */
241:     public GridLayout2(int r, int c, int hgap, int vgap) {
242: 	if ((r == 0) && (c == 0)) {
243: 	    throw new IllegalArgumentException("rows and cols cannot "
244: 					       + "both be zero");
245: 	}
246: 	this.rows = r;
247: 	this.cols = c;
248: 	this.h = hgap;
249: 	this.vgap = vgap;
