252:     /**
253:      * Construct a new GridLayout2 with the specified number of rows
254:      * and columns and cell sizing scheme.
255:      *
256:      * @param r the number of rows in the layout
257:      * @param cols the number of columns in the layout
258:      * @param cellSizing the required cell sizing scheme
259:      */
260:     public GridLayout2(int r, int cols, int cellSizing) {
261: 	this(r, cols, 0, 0, cellSizing);
262:     }
263: 
264:     /**
265:      * Construct a new GridLayout2 with the specified number of rows
266:      * and columns, cell spacing and cell sizing scheme.
267:      *
268:      * @param r the number of rows in the layout
269:      * @param cols the number of columns in the layout
270:      * @param hgap the horizontal gap between cells
271:      * @param vgap the vertical gap between cells
272:      * @param cellSizing the required cell sizing scheme
273:      */
274:     public GridLayout2(int r, int cols, int hgap, int vgap, int cellSizing) {
275:         this(r, cols, hgap, vgap);
276:         this.cellSizing = cellSizing;
277:     }
278: 
279:     /**
280:      * Construct a new GridLayout2 with the specified number of rows
281:      * and columns, cell spacing, cell sizing scheme and filling
