213:     /**
214:      * Construct a new GridLayout2 with a default of one column per
215:      * component, in a single row.
216:      */
217:     public GridLayout2() {
218: 	this(1, 0, 0, 0);
219:     }
220: 
221:     /**
222:      * Construct a new GridLayout2 with the specified number of rows
223:      * and columns.
224:      *
225:      * @param r the number of rows in the layout
226:      * @param c the number of columns in the layout
227:      */
228:     public GridLayout2(int r, int c) {
229: 	this(r, c, 0, 0);
230:     }
231: 
232:     /**
233:      * Construct a new GridLayout2 with the specified number of rows
234:      * and columns and cell spacing.
235:      *
236:      * @param r the number of rows in the layout
237:      * @param c the number of columns in the layout
238:      * @param hgap the horizontal gap between cells
239:      * @param vgap the vertical gap between cells
240:      */
241:     public GridLayout2(int r, int c, int hgap, int vgap) {
242: 	if ((r == 0) && (c == 0)) {
243: 	    throw new IllegalArgumentException("rows and cols cannot "
244: 					       + "both be zero");
245: 	}
246: 	this.rows = r;
247: 	this.cols = c;
248: 	this.h = hgap;
249: 	this.vgap = vgap;
250:     }
251: 
252:     /**
253:      * Construct a new GridLayout2 with the specified number of rows
254:      * and columns and cell sizing scheme.
255:      *
256:      * @param r the number of rows in the layout
257:      * @param c the number of columns in the layout
258:      * @param cellSizing the required cell sizing scheme
259:      */
260:     public GridLayout2(int r, int c, int cellSizing) {
261: 	this(r, c, 0, 0, cellSizing);
262:     }
263: 
264:     /**
